(window.APUSH_TOPICS=window.APUSH_TOPICS||{})[2]=[{"id": "p2-001", "period": 2, "topic_en": "Restoration proprietary grants: Carolina (1663) and New York (1664)", "topic_zh": "王政复辟时期的领主殖民地：卡罗来纳（1663）与纽约（1664）", "year": 1663, "year_text": "1663-1664", "who": ["Charles II"], "who_zh": ["查理二世"], "what_en": "After his restoration, Charles II granted vast American lands to loyal proprietors: the Carolina proprietorship in 1663 and, after the English seized New Netherland in 1664, the colony of New York (plus New Jersey).", "what_zh": "王政复辟后，查理二世将大片美洲土地授予忠诚的领主：1663年卡罗来纳领主殖民地，以及1664年夺取新尼德兰后建立的纽约殖民地（及新泽西）。", "cause_en": "Charles II rewarded political allies who had supported the restoration of the Stuart monarchy, and England wanted to dislodge the Dutch from the Atlantic coast.", "cause_zh": "查理二世奖赏支持斯图亚特王朝复辟的政治盟友，同时英国希望将荷兰人逐出大西洋沿岸。", "sig_en": "Proprietorships planted English authority along the coast, but proprietors' efforts to control land, religion, and trade bred conflict with settlers and prepared the ground for later royal takeovers.", "sig_zh": "领主制把英国权威植入沿岸，但领主对土地、宗教与贸易的控制引发与移民的冲突，为日后王室接管埋下伏笔。", "exp_en": "Restoration-era proprietary grants expanded England's mainland empire and displaced the Dutch, yet the proprietors' ambitious controls repeatedly collided with colonial self-interest.", "exp_zh": "复辟时期的领主授予扩大了英国本土帝国、驱逐了荷兰人，但领主的强力管控屡屡与殖民地自身利益冲突。", "page": 82, "topic_es": "Concesiones propietarias de la Restauración: Carolina (1663) y New York (1664)", "what_es": "Tras su restauración, Charles II otorgó vastas tierras americanas a propietarios leales: la propiedad de Carolina en 1663 y, después de que los ingleses arrebataran New Netherland a los holandeses en 1664, la colonia de New York (más New Jersey).", "cause_es": "Charles II recompensó a los aliados políticos que habían apoyado la restauración de la monarquía Estuardo, e Inglaterra quería desalojar a los holandeses de la costa atlántica.", "sig_es": "Las propiedades plantaron la autoridad inglesa a lo largo de la costa, pero los esfuerzos de los propietarios por controlar la tierra, la religión y el comercio generaron conflictos con los colonos y prepararon el terreno para posteriores tomas de control reales.", "exp_es": "Las concesiones propietarias de la época de la Restauración expandieron el imperio continental inglés y desplazaron a los holandeses, pero los ambiciosos controles de los propietarios chocaron repetidamente con el interés propio colonial.", "who_es": ["Charles II"]}, {"id": "p2-002", "period": 2, "topic_en": "William Penn and the founding of Pennsylvania (1681)", "topic_zh": "威廉·佩恩与宾夕法尼亚的建立（1681）", "year": 1681, "year_text": "1681", "who": ["William Penn", "Quakers", "George Fox", "Margaret Fell"], "who_zh": ["威廉·佩恩", "贵格会", "乔治·福克斯", "玛格丽特·费尔"], "what_en": "In 1681 William Penn founded Pennsylvania as a Quaker refuge, guided by the belief that God had imbued all people with an 'inner light'; his Frame of Government (1681) banned an established church and let all property-owning men vote and hold office.", "what_zh": "1681年威廉·佩恩建立宾夕法尼亚作为贵格会避难所，其信条是上帝赋予所有人“内在之光”；其《政府纲领》（1681）禁止设立国教，允许所有有产男性投票和担任公职。", "cause_en": "Penn wanted a colony where Quakers persecuted in England could worship freely, and he negotiated Indian land purchases, such as the 1682 treaty with the Delaware Indians, to avoid the violence of earlier frontiers.", "cause_zh": "佩恩希望为在英国受迫害的贵格会建立可自由信仰的殖民地，并通过与印第安人谈判购买土地（如1682年与特拉华人的条约）避免早年边疆的暴力。", "sig_en": "Pennsylvania became the most open and democratic of the Restoration colonies, drawing Quakers and thousands of Germans (Germantown, 1683), and its pacifist, tolerant model shaped the diverse Middle colonies.", "sig_zh": "宾夕法尼亚成为复辟时期殖民地中最开放民主的一个，吸引贵格会与数千德意志移民（1683年日耳曼敦），其和平主义与宽容模式塑造了多元的中部殖民地。", "exp_en": "Penn's 'holy experiment' fused religious toleration with democratic politics, but its pacifism and open land policies would later strain relations with both Native Americans and aggressive backcountry settlers.", "exp_zh": "佩恩的“神圣实验”将宗教宽容与民主政治结合，但其和平主义与开放的土地政策日后在印第安人与激进边疆移民之间左右为难。", "page": 82, "topic_es": "William Penn y la fundación de Pennsylvania (1681)", "what_es": "En 1681 William Penn fundó Pennsylvania como refugio cuáquero, guiado por la creencia de que Dios había dotado a todas las personas de una 'luz interior'; su Frame of Government (1681) prohibió una iglesia establecida y permitió a todos los hombres propietarios votar y ocupar cargos.", "cause_es": "Penn quería una colonia donde los cuáqueros perseguidos en Inglaterra pudieran adorar libremente, y negoció compras de tierras indias, como el tratado de 1682 con los indios Delaware, para evitar la violencia de fronteras anteriores.", "sig_es": "Pennsylvania se convirtió en la más abierta y democrática de las colonias de la Restauración, atrayendo a cuáqueros y a miles de alemanes (Germantown, 1683), y su modelo pacifista y tolerante dio forma a las diversas colonias medias.", "exp_es": "El 'experimento sagrado' de Penn fusionó la tolerancia religiosa con la política democrática, pero su pacifismo y sus políticas abiertas de tierras tensarían más tarde las relaciones tanto con los nativos americanos como con los agresivos colonos de la frontera.", "who_es": ["William Penn", "cuáqueros", "George Fox", "Margaret Fell"]}, {"id": "p2-003", "period": 2, "topic_en": "Navigation Acts (1651-1751)", "topic_zh": "《航海法案》（1651–1751）", "year": 1651, "year_text": "1651-1751", "who": [], "who_zh": [], "what_en": "Parliament's Navigation Acts (1651, 1660, 1663, and others) required colonial goods to be carried on English ships and enumerated products like sugar and tobacco to be exported only to England, enforced by customs officials paid through the Revenue Act of 1673.", "what_zh": "议会《航海法案》（1651、1660、1663年及后续）要求殖民地货物由英国船只运输，糖、烟草等“列举商品”只能出口到英国，由《1673年税收法》供养的海关官员执行。", "cause_en": "English ministers followed mercantilist strategy: controlling colonial trade would keep the profits of American products in English hands and cut out Dutch and French shippers.", "cause_zh": "英国大臣奉行重商主义战略：控制殖民地贸易可使美洲产品利润留在英国人手中，并排挤荷兰与法国船商。", "sig_en": "The acts enriched English merchants and the crown but taught colonists to evade imperial trade law — Massachusetts openly claimed English laws 'do not reach America' — planting habits of resistance to mercantilist control.", "sig_zh": "法案使英国商人与王室获利，却也让殖民者学会规避帝国贸易法——马萨诸塞公开宣称英国法律“不及于美洲”——培养了抵制重商主义管控的习惯。", "why_term": "mercantilism", "why_term_q": "英国用《航海法案》控制殖民地贸易的经济思想是______。", "exp_en": "The Navigation Acts were the legal backbone of the mercantilist empire: they secured England's commercial gains while normalizing colonial smuggling and constitutional defiance.", "exp_zh": "《航海法案》是重商主义帝国的法律支柱：它保障了英国的商业利益，也使殖民地的走私与违宪抗命常态化。", "page": 83, "topic_es": "Navigation Acts (1651-1751)", "what_es": "Las Navigation Acts del Parlamento (1651, 1660, 1663 y otras) exigían que las mercancías coloniales se transportaran en barcos ingleses y que productos enumerados como el azúcar y el tabaco solo se exportaran a Inglaterra, aplicadas por funcionarios de aduanas pagados mediante la Revenue Act de 1673.", "cause_es": "Los ministros ingleses seguían la estrategia mercantilista: controlar el comercio colonial mantendría los beneficios de los productos americanos en manos inglesas y excluiría a los transportistas holandeses y franceses.", "sig_es": "Las leyes enriquecieron a los comerciantes ingleses y a la corona, pero enseñaron a los colonos a evadir la ley comercial imperial — Massachusetts afirmó abiertamente que las leyes inglesas 'no alcanzan a América' — sembrando hábitos de resistencia al control mercantilista.", "exp_es": "Las Navigation Acts fueron la columna vertebral legal del imperio mercantilista: aseguraron las ganancias comerciales de Inglaterra mientras normalizaban el contrabando colonial y el desafío constitucional.", "who_es": [], "why_term_q_es": "La doctrina económica con la que Inglaterra controlaba el comercio colonial mediante las Navigation Acts es ______."}, {"id": "p2-004", "period": 2, "topic_en": "Dominion of New England (1686-1689)", "topic_zh": "新英格兰自治领（1686–1689）", "year": 1686, "year_text": "1686-1689", "who": ["James II", "Edmund Andros"], "who_zh": ["詹姆斯二世", "埃德蒙·安德罗斯"], "what_en": "James II merged Massachusetts Bay, Plymouth, Connecticut, and Rhode Island (later New York and New Jersey) into the Dominion of New England under Governor Edmund Andros, who abolished assemblies and town meetings, promoted the Church of England, and invalidated existing land titles.", "what_zh": "詹姆斯二世将马萨诸塞湾、普利茅斯、康涅狄格和罗得岛（后加纽约、新泽西）合并为新英格兰自治领，由埃德蒙·安德罗斯任总督，废除议会和镇民大会、推行英国国教、宣布既有土地所有权无效。", "cause_en": "James admired the authoritarian rule of Louis XIV of France and wanted strict royal control over colonies that had been defying the Navigation Acts, as the Lords of Trade's 1684 annulment of the Massachusetts charter showed.", "cause_zh": "詹姆斯二世推崇法国路易十四的专制统治，希望对屡屡违抗《航海法案》的殖民地实行严格王室管控，贸易领主委员会1684年撤销马萨诸塞特许状即为前奏。", "sig_en": "Andros's heavy-handed rule united colonists in hatred of arbitrary government; when the Glorious Revolution toppled James, Bostonians overthrew Andros and the Dominion collapsed, teaching colonists the power of collective resistance.", "sig_zh": "安德罗斯的高压统治使殖民者同仇敌忾；光荣革命推翻詹姆斯后，波士顿人推翻安德罗斯、自治领瓦解，殖民者由此学会了集体反抗的力量。", "exp_en": "The Dominion was the Stuart attempt to impose Ireland-style authoritarian rule on America; its failure convinced colonists that representative institutions were worth defending.", "exp_zh": "自治领是斯图亚特王朝把爱尔兰式专制统治强加于美洲的尝试；它的失败让殖民者确信代议制度值得捍卫。", "page": 85, "topic_es": "Dominion of New England (1686-1689)", "what_es": "James II fusionó Massachusetts Bay, Plymouth, Connecticut y Rhode Island (más tarde New York y New Jersey) en el Dominion of New England bajo el gobernador Edmund Andros, quien abolió asambleas y reuniones municipales, promovió la Iglesia de Inglaterra e invalidó los títulos de tierras existentes.", "cause_es": "James admiraba el gobierno autoritario de Louis XIV de Francia y quería un estricto control real sobre colonias que venían desafiando las Navigation Acts, como mostró la anulación de la carta de Massachusetts por los Lords of Trade en 1684.", "sig_es": "El gobierno autoritario de Andros unió a los colonos en el odio al gobierno arbitrario; cuando la Revolución Gloriosa derrocó a James, los bostonianos derrocaron a Andros y el Dominio colapsó, enseñando a los colonos el poder de la resistencia colectiva.", "exp_es": "El Dominio fue el intento Estuardo de imponer en América un gobierno autoritario al estilo irlandés; su fracaso convenció a los colonos de que valía la pena defender las instituciones representativas.", "who_es": ["James II", "Edmund Andros"], "img": {"file": "img:f1_2133", "credit": "图源：Henretta《America's History》第8版 p.85"}}, {"id": "p2-005", "period": 2, "topic_en": "Glorious Revolution in England (1688-1689)", "topic_zh": "英国光荣革命（1688–1689）", "year": 1688, "year_text": "1688-1689", "who": ["William of Orange", "Mary Stuart", "James II"], "who_zh": ["奥兰治的威廉", "玛丽·斯图亚特", "詹姆斯二世"], "what_en": "Whig leaders invited the Protestant Dutch prince William of Orange to invade England; he quickly deposed the Catholic James II, and William and Mary accepted the Declaration of Rights, creating a constitutional monarchy that strengthened the House of Commons.", "what_zh": "辉格党领袖邀请信奉新教的荷兰王子奥兰治的威廉入侵英国；他迅速废黜天主教的詹姆斯二世，威廉与玛丽接受《权利宣言》，建立了强化下议院权力的君主立宪制。", "cause_en": "James II had revoked town charters, defied Parliament, and openly practiced Catholicism; the birth of his Catholic son in 1688 threatened a permanent Catholic succession.", "cause_zh": "詹姆斯二世撤销城镇特许状、蔑视议会、公开信奉天主教；1688年其天主教儿子的出生预示着天主教世袭统治将永久化。", "sig_en": "The revolution ended Stuart absolutism and created a constitutional monarchy; in America it triggered the overthrow of the Dominion and inspired colonial assemblies to copy the Whigs by limiting crown officials' power.", "sig_zh": "革命终结了斯图亚特专制、建立了君主立宪；在美洲它引发了自治领的推翻，并激励殖民地议会效仿辉格党限制王室官员权力。", "why_term": "constitutional monarchy", "why_term_q": "1688–1689年革命后英国建立的政体被称为______。", "exp_en": "The Glorious Revolution was the political watershed that linked English liberty to colonial self-government: Whig principles crossed the Atlantic and armed the assemblies against royal governors.", "exp_zh": "光荣革命是把英国自由与殖民地自治相连的政治分水岭：辉格原则漂洋过海，武装了议会去对抗王室总督。", "page": 86, "topic_es": "La Revolución Gloriosa en Inglaterra (1688-1689)", "what_es": "Los líderes whig invitaron al príncipe protestante holandés William of Orange a invadir Inglaterra; este depuso rápidamente al católico James II, y William y Mary aceptaron la Declaración de Derechos, creando una monarquía constitucional que fortaleció la Cámara de los Comunes.", "cause_es": "James II había revocado cartas municipales, desafiado al Parlamento y practicado abiertamente el catolicismo; el nacimiento de su hijo católico en 1688 amenazaba una sucesión católica permanente.", "sig_es": "La revolución puso fin al absolutismo Estuardo y creó una monarquía constitucional; en América provocó el derrocamiento del Dominio e inspiró a las asambleas coloniales a imitar a los whigs limitando el poder de los funcionarios de la corona.", "exp_es": "La Revolución Gloriosa fue el parteaguas político que vinculó la libertad inglesa con el autogobierno colonial: los principios whig cruzaron el Atlántico y armaron a las asambleas contra los gobernadores reales.", "who_es": ["William of Orange", "Mary Stuart", "James II"], "why_term_q_es": "El sistema político establecido en Inglaterra tras la revolución de 1688–1689 se denomina ______.", "img": {"file": "img:f1_2139", "credit": "图源：Henretta《America's History》第8版 p.86"}}, {"id": "p2-006", "period": 2, "topic_en": "John Locke's Two Treatises of Government (1690)", "topic_zh": "约翰·洛克《政府论》（1690）", "year": 1690, "year_text": "1690", "who": ["John Locke"], "who_zh": ["约翰·洛克"], "what_en": "In Two Treatises of Government (1690) Locke rejected divine-right monarchy, arguing that legitimate government rests on the consent of the governed and that individuals hold inalienable natural rights to life, liberty, and property.", "what_zh": "在《政府论》（1690）中，洛克否定君权神授，主张合法政府建立在被统治者同意之上，个人拥有生命、自由和财产等不可剥夺的自然权利。", "cause_en": "Parliament needed an intellectual justification for deposing James II, and Locke supplied a theory that made the Whig coup legitimate.", "cause_zh": "议会需要为废黜詹姆斯二世提供思想辩护，洛克的理论使辉格党的政变得以合法化。", "sig_en": "Locke's celebration of individual rights and representative government had a lasting influence in America, where colonial leaders used it to expand the powers of the assemblies — and later, to justify revolution.", "sig_zh": "洛克对个人权利与代议政府的颂扬在美国影响深远，殖民地领袖用它来扩大议会权力——后来更用来论证革命的正当性。", "why_term": "natural rights", "why_term_q": "洛克主张个人拥有的生命、自由、财产等不可剥夺的权利称为______。", "exp_en": "Locke turned the Glorious Revolution's politics into philosophy: consent and natural rights became the vocabulary of every later colonial challenge to imperial authority.", "exp_zh": "洛克把光荣革命的政治变成了哲学：同意与自然权利成为此后每一次殖民地挑战帝国权威的话语。", "page": 86, "topic_es": "Two Treatises of Government de John Locke (1690)", "what_es": "En Two Treatises of Government (1690), Locke rechazó la monarquía de derecho divino, argumentando que el gobierno legítimo descansa en el consentimiento de los gobernados y que los individuos poseen derechos naturales inalienables a la vida, la libertad y la propiedad.", "cause_es": "El Parlamento necesitaba una justificación intelectual para deponer a James II, y Locke aportó una teoría que legitimaba el golpe whig.", "sig_es": "La exaltación lockeana de los derechos individuales y el gobierno representativo tuvo una influencia duradera en América, donde los líderes coloniales la usaron para ampliar los poderes de las asambleas — y más tarde, para justificar la revolución.", "exp_es": "Locke convirtió la política de la Revolución Gloriosa en filosofía: el consentimiento y los derechos naturales se volvieron el vocabulario de cada posterior desafío colonial a la autoridad imperial.", "who_es": ["John Locke"], "why_term_q_es": "Los derechos inalienables a la vida, la libertad y la propiedad que Locke atribuía a cada persona se denominan ______.", "img": {"file": "img:f1_2139", "credit": "图源：Henretta《America's History》第8版 p.86"}}, {"id": "p2-007", "period": 2, "topic_en": "Colonial rebellions of 1689", "topic_zh": "1689年殖民地起义", "year": 1689, "year_text": "1689-1691", "who": ["Jacob Leisler"], "who_zh": ["雅各布·莱斯勒"], "what_en": "News of the Glorious Revolution sparked Protestant uprisings: Boston militiamen seized Governor Andros; Maryland's Protestant Association ousted the Catholic governor; and in New York Jacob Leisler led a rebellion, later hanged for treason in 1691 after Governor Sloughter's arrival.", "what_zh": "光荣革命的消息引发新教徒起义：波士顿民兵逮捕安德罗斯总督；马里兰的新教徒协会驱逐天主教总督；纽约的雅各布·莱斯勒领导起义，1691年斯劳特总督到任后以叛国罪将其绞死。", "cause_en": "Colonists resented the Dominion's authoritarian rule and, in Maryland, Catholic proprietary officials' taxes amid falling tobacco prices; the fall of James II gave them an opening to strike.", "cause_zh": "殖民者痛恨自治领的专制统治，马里兰人还不满天主教领主官员在烟草价格下跌时加税；詹姆斯二世的倒台给了他们动手的时机。", "sig_en": "The new monarchs broke up the Dominion but refused to restore the old Puritan government, instead imposing royal colonies and new charters — while in Maryland the Lords of Trade imposed royal rule and the Anglican establishment until 1715.", "sig_zh": "新君主解散了自治领，却拒绝恢复旧清教政府，代之以王室殖民地与新特许状；马里兰则被贸易领主置于王室统治并确立国教地位，直至1715年。", "exp_en": "The 1689 rebellions showed colonists could topple imperial officials, but the crown's response — new royal charters rather than restored autonomy — kept the struggle over self-government alive.", "exp_zh": "1689年起义证明殖民者能推翻帝国官员，但王室的回应——颁发新的王室特许状而非恢复自治——使自治之争延续下去。", "page": 87, "topic_es": "Rebeliones coloniales de 1689", "what_es": "La noticia de la Revolución Gloriosa desató levantamientos protestantes: milicianos de Boston apresaron al gobernador Andros; la Asociación Protestante de Maryland depuso al gobernador católico; y en New York, Jacob Leisler encabezó una rebelión, y más tarde fue ahorcado por traición en 1691 tras la llegada del gobernador Sloughter.", "cause_es": "Los colonos resentían el gobierno autoritario del Dominio y, en Maryland, los impuestos de los funcionarios propietarios católicos en medio de la caída de los precios del tabaco; la caída de James II les dio la oportunidad de actuar.", "sig_es": "Los nuevos monarcas disolvieron el Dominio pero se negaron a restaurar el antiguo gobierno puritano, imponiendo en cambio colonias reales y nuevas cartas — mientras que en Maryland los Lords of Trade impusieron el gobierno real y el establecimiento anglicano hasta 1715.", "exp_es": "Las rebeliones de 1689 mostraron que los colonos podían derrocar a funcionarios imperiales, pero la respuesta de la corona — nuevas cartas reales en lugar de la autonomía restaurada — mantuvo viva la lucha por el autogobierno.", "who_es": ["Jacob Leisler"], "img": {"file": "img:f1_2143", "credit": "图源：Henretta《America's History》第8版 p.87"}}, {"id": "p2-008", "period": 2, "topic_en": "Board of Trade (1696)", "topic_zh": "贸易委员会（1696）", "year": 1696, "year_text": "1696", "who": [], "who_zh": [], "what_en": "In 1696 Parliament created the Board of Trade, a new imperial body charged with overseeing colonial affairs and tightening enforcement of the Navigation Acts through measures like vice-admiralty courts.", "what_zh": "1696年议会设立贸易委员会，作为负责监督殖民地事务、通过海事法庭等手段强化《航海法案》执行的新帝国机构。", "cause_en": "After the Glorious Revolution, William and Mary accepted the end of the Dominion but still wanted an empire based on commerce, so they built a bureaucracy to manage colonial trade and obedience.", "cause_zh": "光荣革命后，威廉与玛丽接受了自治领的终结，但仍想要一个以商业为基础的帝国，于是建立官僚机构来管理殖民地贸易与服从。", "sig_en": "The Board of Trade became the crown's instrument for challenging colonial assemblies — its governors, like Spotswood and Clinton, spent decades complaining that the assemblies were usurping imperial prerogatives.", "sig_zh": "贸易委员会成为王室挑战殖民地议会的工具——其总督们（如斯波茨伍德、克林顿）数十年抱怨议会僭越帝国特权。", "exp_en": "The Board of Trade embodied the post-1689 compromise: no more Dominion-style absolutism, but a steady bureaucratic pressure to bring colonial trade and politics under London's direction.", "exp_zh": "贸易委员会体现了1689年后的妥协：不再有自治领式专制，但以持续的官僚压力把殖民地贸易与政治纳入伦敦轨道。", "page": 87, "topic_es": "Board of Trade (1696)", "what_es": "En 1696 el Parlamento creó el Board of Trade, un nuevo organismo imperial encargado de supervisar los asuntos coloniales y de reforzar el cumplimiento de las Navigation Acts mediante medidas como los tribunales del vicealmirantazgo.", "cause_es": "Tras la Revolución Gloriosa, William y Mary aceptaron el fin del Dominio pero seguían queriendo un imperio basado en el comercio, así que construyeron una burocracia para gestionar el comercio colonial y la obediencia.", "sig_es": "El Board of Trade se convirtió en el instrumento de la corona para desafiar a las asambleas coloniales — sus gobernadores, como Spotswood y Clinton, pasaron décadas quejándose de que las asambleas usurpaban las prerrogativas imperiales.", "exp_es": "El Board of Trade encarnó el compromiso posterior a 1689: no más absolutismo al estilo del Dominio, pero una presión burocrática constante para someter el comercio y la política coloniales a la dirección de Londres.", "who_es": [], "img": {"file": "img:f1_2143", "credit": "图源：Henretta《America's History》第8版 p.87"}}, {"id": "p2-009", "period": 2, "topic_en": "Second Hundred Years' War begins (1689-1713)", "topic_zh": "第二次百年战争开端（1689–1713）", "year": 1689, "year_text": "1689-1713", "who": [], "who_zh": [], "what_en": "The Glorious Revolution opened a long era of imperial warfare: between 1689 and 1713 England, France, and Spain fought in America and Europe, with French-allied Indians destroying Deerfield, Massachusetts in 1704 (48 killed, 112 taken captive) and New Englanders seizing Port Royal in 1710.", "what_zh": "光荣革命开启了长期的帝国战争时代：1689至1713年间英、法、西在美洲与欧洲交战，法国盟友印第安人1704年摧毁马萨诸塞迪尔菲尔德（48死、112人被俘），新英格兰人1710年攻占皇家港。", "cause_en": "William of Orange brought England into his Dutch-led coalition against Louis XIV's France, and colonial rivalries over trade and territory turned the contest into an American war as well.", "cause_zh": "奥兰治的威廉把英国带入其领导的反路易十四联盟，殖民地在贸易与领土上的竞争使这场较量也成为美洲战争。", "sig_en": "Imperial warfare exposed Native communities to danger but gave them leverage as sought-after allies, and it taught colonial militiamen to fight — while making the colonies' security dependent on London's wars.", "sig_zh": "帝国战争使印第安社群面临危险，却也赋予他们作为被争抢盟友的筹码；殖民地民兵学会了打仗，殖民地安全也从此系于伦敦的战争。", "exp_en": "The wars of 1689-1713 wove the colonies into a transatlantic military system: local frontier raids were now episodes in a global struggle for empire.", "exp_zh": "1689–1713年的战争把殖民地织入跨大西洋军事体系：地方边疆袭击从此成为全球帝国争霸的插曲。", "page": 88, "topic_es": "Comienzo de la Segunda Guerra de los Cien Años (1689-1713)", "what_es": "La Revolución Gloriosa abrió una larga era de guerra imperial: entre 1689 y 1713 Inglaterra, Francia y España lucharon en América y Europa; indios aliados de los franceses destruyeron Deerfield, Massachusetts, en 1704 (48 muertos, 112 cautivos) y los habitantes de New England tomaron Port Royal en 1710.", "cause_es": "William of Orange incorporó a Inglaterra a su coalición liderada por los holandeses contra la Francia de Louis XIV, y las rivalidades coloniales por el comercio y el territorio convirtieron la contienda también en una guerra americana.", "sig_es": "La guerra imperial expuso a las comunidades nativas al peligro pero les dio influencia como aliados codiciados, y enseñó a combatir a los milicianos coloniales — al tiempo que hacía depender la seguridad de las colonias de las guerras de Londres.", "exp_es": "Las guerras de 1689-1713 tejieron a las colonias en un sistema militar transatlántico: las incursiones fronterizas locales eran ahora episodios de una lucha global por el imperio.", "who_es": []}, {"id": "p2-010", "period": 2, "topic_en": "Treaty of Utrecht (1713)", "topic_zh": "《乌得勒支条约》（1713）", "year": 1713, "year_text": "1713", "who": [], "who_zh": [], "what_en": "Ending Queen Anne's War, the Treaty of Utrecht (1713) gave Britain Newfoundland, Acadia, and the Hudson Bay region from France, plus Gibraltar and a thirty-year contract to supply slaves to Spanish America from Spain.", "what_zh": "结束安妮女王战争的《乌得勒支条约》（1713）使英国从法国获得纽芬兰、阿卡迪亚和哈德逊湾地区，从西班牙获得直布罗陀及向西属美洲供应奴隶三十年的合同。", "cause_en": "Stalemated militarily in America but victorious in Europe, Britain converted its continental gains into colonial concessions at the peace table.", "cause_zh": "英国在美洲战场陷入僵持但在欧洲获胜，于是在和谈桌上把欧洲战果转化为殖民地让步。", "sig_en": "The treaty advanced Britain's quest for commercial supremacy and brought peace to eastern North America for a generation, setting the stage for the South Atlantic System's boom.", "sig_zh": "条约推进了英国谋求商业霸权的进程，使北美东部获得一代人的和平，为南大西洋体系的繁荣铺平道路。", "exp_en": "Utrecht marked Britain's arrival as the dominant Atlantic power: territory, trade, and the slave contract all flowed to London.", "exp_zh": "乌得勒支标志着英国成为大西洋主导力量：领土、贸易与奴隶合同尽归伦敦。", "page": 90, "topic_es": "Treaty of Utrecht (1713)", "what_es": "Al poner fin a la Guerra de la Reina Ana, el Treaty of Utrecht (1713) otorgó a Gran Bretaña Newfoundland, Acadia y la región de la Bahía de Hudson arrebatadas a Francia, además de Gibraltar y un contrato de treinta años para suministrar esclavos a la América española.", "cause_es": "Militarmente estancada en América pero victoriosa en Europa, Gran Bretaña convirtió sus ganancias continentales en concesiones coloniales en la mesa de paz.", "sig_es": "El tratado avanzó la búsqueda británica de la supremacía comercial y trajo paz al este de Norteamérica por una generación, preparando el escenario para el auge del Sistema Atlántico Sur.", "exp_es": "Utrecht marcó la llegada de Gran Bretaña como potencia atlántica dominante: territorio, comercio y el contrato esclavista fluyeron hacia Londres.", "who_es": []}, {"id": "p2-011", "period": 2, "topic_en": "Covenant Chain and Iroquois neutrality (1701)", "topic_zh": "契约链与易洛魁中立（1701）", "year": 1701, "year_text": "1701", "who": ["Iroquois"], "who_zh": ["易洛魁人"], "what_en": "After French-allied forces burned the Mohawk villages in 1693, the Iroquois in 1701 made alliances with both France and England, declaring neutrality in future imperial wars; their alliance with New York, the Covenant Chain, became the model for British-Indian diplomacy.", "what_zh": "1693年法国盟军烧毁莫霍克村庄后，易洛魁人1701年同时与法、英结盟，宣布在未来帝国战争中保持中立；其与纽约的盟约“契约链”成为英印外交的样板。", "cause_en": "The Iroquois had been endangered by imperial conflict and a failed English alliance, so they devised a strategy of playing French and English interests against each other to survive.", "cause_zh": "易洛魁人在帝国冲突中岌岌可危、英国盟约又靠不住，于是设计出在法英利益之间周旋求存的策略。", "sig_en": "Their neutrality paradoxically made them more sought after as allies, and the Iroquois became Britain's indispensable partner in Indian relations through the mid-1700s.", "sig_zh": "其中立反而使其成为更被争抢的盟友，易洛魁成为18世纪中期英国印第安关系的不可或缺伙伴。", "exp_en": "The Covenant Chain shows how Native peoples turned imperial rivalry into diplomatic power — at least until Britain's 1763 victory removed the French counterweight.", "exp_zh": "契约链展示了原住民如何把帝国竞争转化为外交筹码——至少在1763年英国胜利消除法国制衡之前如此。", "page": 89, "topic_es": "Covenant Chain y la neutralidad de los iroqueses (1701)", "what_es": "Después de que fuerzas aliadas de los franceses incendiaran las aldeas mohawk en 1693, los iroqueses concertaron en 1701 alianzas tanto con Francia como con Inglaterra, declarando su neutralidad en futuras guerras imperiales; su alianza con New York, la Covenant Chain, se convirtió en el modelo de la diplomacia británico-india.", "cause_es": "Los iroqueses se habían visto en peligro por el conflicto imperial y una fallida alianza inglesa, así que idearon una estrategia de enfrentar los intereses franceses e ingleses entre sí para sobrevivir.", "sig_es": "Su neutralidad, paradójicamente, los hizo más codiciados como aliados, y los iroqueses se convirtieron en el socio indispensable de Gran Bretaña en las relaciones indias hasta mediados del siglo XVIII.", "exp_es": "La Covenant Chain muestra cómo los pueblos nativos convirtieron la rivalidad imperial en poder diplomático — al menos hasta que la victoria británica de 1763 eliminó el contrapeso francés.", "who_es": ["iroqueses"], "img": {"file": "img:f1_2149", "credit": "图源：Henretta《America's History》第8版 p.89"}}, {"id": "p2-012", "period": 2, "topic_en": "Tribalization and the Yamasee War (1715)", "topic_zh": "部落化与亚马西战争（1715）", "year": 1715, "year_text": "1715", "who": ["Creek", "Yamasee", "Tuscarora", "Cherokee"], "who_zh": ["克里克人", "亚马西人", "塔斯卡罗拉人", "切罗基人"], "what_en": "Pressured by European contact, fragmented peoples coalesced into 'tribes' like the Creeks; after Carolina traders demanded payment for debts in 1715, the Creeks and Yamasees revolted and killed 400 colonists, while the defeated Tuscaroras fled north to join the Iroquois as the Six Nations.", "what_zh": "在欧洲接触的压力下，分散的族群凝聚为“部落”（如克里克人）；1715年卡罗来纳商人索要贸易欠款后，克里克与亚马西人起义、杀死400名殖民者，战败的塔斯卡罗拉人北逃加入易洛魁，成为“六族”。", "cause_en": "The English armed the Creeks for wars against the Spanish and Tuscaroras, then squeezed them for trade debts; tribalization itself was a defensive response to make fragmented groups effective negotiators with Europeans.", "cause_zh": "英国人先武装克里克人去打西班牙人和塔斯卡罗拉人，转身又逼其偿还贸易欠款；部落化本身是分散族群为有效与欧洲人谈判而采取的防御性整合。", "sig_en": "The Yamasee War broke the power of the coastal tribes in the Southeast and taught the Carolinians to depend on the Cherokees, reshaping the region's Indian diplomacy for decades.", "sig_zh": "亚马西战争摧毁了东南部沿海部落的力量，使卡罗来纳人转而依赖切罗基人，重塑了该地区数十年的印第安外交。", "exp_en": "Tribalization was Native America's creative adaptation to empire: new 'tribes' were political inventions forged in the fire of the slave trade and imperial war.", "exp_zh": "部落化是美洲原住民对帝国的创造性适应：新的“部落”是在奴隶贸易与帝国战争烈火中锻造的政治发明。", "page": 90, "topic_es": "Tribalización y la Guerra Yamasee (1715)", "what_es": "Presionados por el contacto europeo, pueblos fragmentados se fusionaron en 'tribus' como los creeks; después de que comerciantes de Carolina exigieran en 1715 el pago de deudas, los creeks y yamasees se rebelaron y mataron a 400 colonos, mientras los derrotados tuscaroras huyeron al norte para unirse a los iroqueses como las Seis Naciones.", "cause_es": "Los ingleses habían armado a los creeks para guerras contra los españoles y tuscaroras, y luego los exprimieron por deudas comerciales; la tribalización misma fue una respuesta defensiva para que los grupos fragmentados negociaran eficazmente con los europeos.", "sig_es": "La Guerra Yamasee quebró el poder de las tribus costeras del Sureste y enseñó a los habitantes de Carolina a depender de los cheroquis, remodelando la diplomacia india de la región por décadas.", "exp_es": "La tribalización fue la adaptación creativa de la América nativa al imperio: nuevas 'tribus' eran invenciones políticas forjadas en el fuego del comercio de esclavos y la guerra imperial.", "who_es": ["creeks", "yamasees", "tuscaroras", "cheroquis"]}, {"id": "p2-013", "period": 2, "topic_en": "South Atlantic System", "topic_zh": "南大西洋体系", "year": null, "year_text": "1650-1750", "who": [], "who_zh": [], "what_en": "The South Atlantic System, centered on Brazil and the West Indies with sugar as its primary product, linked European capital, African slave labor, and American plantations into one commercial order worked by hundreds of thousands of enslaved Africans.", "what_zh": "以巴西和西印度群岛为中心、以糖为主要产品的南大西洋体系，把欧洲资本、非洲奴隶劳工和美洲种植园连成一个商业秩序，依靠数十万被奴役的非洲人运转。", "cause_en": "European craving for sugar created a ready market, and mercantilist investors supplied plantations with tools, ships, and — decisively — the Atlantic slave trade, which made the system run.", "cause_zh": "欧洲人对糖的渴求创造了现成市场，重商主义投资者为种植园提供工具、船只——以及决定性的大西洋奴隶贸易，使体系得以运转。", "sig_en": "The system brought enormous wealth to Britain — by 1750 reshipments of American sugar and tobacco were half of British exports — while creating an exploited African American labor force and prosperous European American farmers and merchants.", "sig_zh": "该体系为英国带来巨额财富——1750年美洲糖烟转口已占英国出口一半——同时造就了被剥削的非洲裔劳工和富裕的欧裔农民与商人。", "exp_en": "The South Atlantic System was the engine of the British Atlantic: it tied plantation slavery, colonial prosperity, and European economic leadership into a single, brutal, profitable machine.", "exp_zh": "南大西洋体系是英属大西洋的引擎：它把种植园奴隶制、殖民地繁荣与欧洲经济领导权拧成一台残酷而牟利的机器。", "page": 90, "topic_es": "Sistema Atlántico Sur", "what_es": "El Sistema Atlántico Sur, centrado en Brasil y las Antillas con el azúcar como producto principal, vinculó el capital europeo, la mano de obra esclava africana y las plantaciones americanas en un orden comercial operado por cientos de miles de africanos esclavizados.", "cause_es": "El ansia europea de azúcar creó un mercado dispuesto, y los inversores mercantilistas abastecieron a las plantaciones con herramientas, barcos y — decisivamente — el comercio atlántico de esclavos, que hacía funcionar el sistema.", "sig_es": "El sistema aportó una enorme riqueza a Gran Bretaña — hacia 1750 las reexportaciones de azúcar y tabaco americanos eran la mitad de las exportaciones británicas — al tiempo que creaba una explotada fuerza laboral afroamericana y prósperos agricultores y comerciantes euroamericanos.", "exp_es": "El Sistema Atlántico Sur fue el motor del Atlántico británico: ató la esclavitud de plantación, la prosperidad colonial y el liderazgo económico europeo en una sola máquina brutal y rentable.", "who_es": []}, {"id": "p2-014", "period": 2, "topic_en": "Middle Passage", "topic_zh": "中间航程", "year": null, "year_text": "1550-1870", "who": ["Olaudah Equiano"], "who_zh": ["奥拉达·埃奎亚诺"], "what_en": "The Middle Passage was the transatlantic leg of the slave trade: Africans marched in chains to coastal ports, then endured a month-long crossing in hideously overcrowded ships, where about 14 percent — some 1.5 million people — died of disease, and slave revolts erupted on roughly one of every ten voyages.", "what_zh": "中间航程是奴隶贸易的跨大西洋一段：非洲人戴着锁链被押往沿海港口，再在恶劣拥挤的船舱中熬过约一个月的航行，约14%（约150万人）死于疾病，每十次航行就有约一次爆发奴隶起义。", "cause_en": "The South Atlantic System's insatiable demand for plantation labor drove European traders to pack ever more captives into ships; between 1550 and 1870 the trade uprooted 11 million Africans.", "cause_zh": "南大西洋体系对种植园劳工永不满足的需求驱使欧洲贩子把越来越多俘虏塞进船舱；1550至1870年间该贸易连根拔起1100万非洲人。", "sig_en": "The Middle Passage's horrors — documented by survivors like Olaudah Equiano in his 1789 narrative — became the moral core of the later abolitionist case against the slave trade.", "sig_zh": "中间航程的惨状——由奥拉达·埃奎亚诺等幸存者在1789年自述中记录——成为后来废奴主义反对奴隶贸易的道德核心。", "src": {"text": "I now saw myself deprived of all chance of returning to my native country. . . . I was soon put down under the decks, and there I received such a salutation in my nostrils as I had never experienced in my life", "attr": "Olaudah Equiano, The Interesting Narrative of the Life of Olaudah Equiano (London, 1789)"}, "exp_en": "The Middle Passage was industrial-scale cruelty: it fed the plantation economy with human cargo and left a trauma that shaped African American memory for centuries.", "exp_zh": "中间航程是工业规模的残酷：它以人体货物喂养种植园经济，留下的创伤塑造了非洲裔美国人几个世纪的记忆。", "page": 94, "topic_es": "Travesía del Atlántico (Middle Passage)", "what_es": "La travesía del Atlántico era la etapa transatlántica del comercio de esclavos: africanos marchaban encadenados a los puertos costeros y luego soportaban una travesía de un mes en barcos horriblemente hacinados, donde alrededor del 14 por ciento — unas 1,5 millones de personas — moría de enfermedades, y las revueltas de esclavos estallaban en aproximadamente uno de cada diez viajes.", "cause_es": "La insaciable demanda de mano de obra para plantaciones del Sistema Atlántico Sur impulsó a los comerciantes europeos a hacinar cada vez más cautivos en los barcos; entre 1550 y 1870 el comercio arrancó de África a 11 millones de africanos.", "sig_es": "Los horrores de la travesía — documentados por sobrevivientes como Olaudah Equiano en su narrativa de 1789 — se convirtieron en el núcleo moral del posterior argumento abolicionista contra el comercio de esclavos.", "exp_es": "La travesía del Atlántico fue crueldad a escala industrial: alimentó la economía de plantación con cargamento humano y dejó un trauma que marcó la memoria afroamericana durante siglos.", "who_es": ["Olaudah Equiano"], "img": {"file": "img:f1_2166", "credit": "图源：Henretta《America's History》第8版 p.94"}}, {"id": "p2-015", "period": 2, "topic_en": "Slavery in the Chesapeake: the tobacco revolution and racial codes", "topic_zh": "切萨皮克的奴隶制：烟草革命与种族法典", "year": null, "year_text": "1680s-1720s", "who": [], "who_zh": [], "what_en": "After Bacon's Rebellion and the end of the Royal African Company's monopoly in 1698, Chesapeake planters led a 'tobacco revolution,' buying more Africans until they were 40 percent of the population by 1740; Virginia defined slavery in racial terms — non-Christian Africans 'shall be accounted and be slaves' — and in 1669 decreed a master who killed a slave while 'correcting' him could not be charged with a felony.", "what_zh": "培根起义后及1698年皇家非洲公司垄断终结后，切萨皮克种植园主掀起“烟草革命”，大量购入非洲人，至1740年占人口40%；弗吉尼亚以种族定义奴隶制——非基督徒非洲人“即视为奴隶”——并在1669年规定主人“管教”中打死奴隶不构成重罪。", "cause_en": "Expanding British slave trade made Africans cheaper and more available just as planters wanted a controllable, lifelong labor force to replace indentured servants after Bacon's Rebellion.", "cause_zh": "培根起义后，种植园主想要可终身控制的劳工以取代契约仆役，恰逢英国奴隶贸易扩张使非洲人更便宜易得。", "sig_en": "Slavery became a core, racially defined institution in the Chesapeake, and the legal violence of the slave codes normalized white mastery — even as tobacco's steadier labor let enslaved families grow and a native-born black majority emerge by midcentury.", "sig_zh": "奴隶制成为切萨皮克以种族定义的核心制度，奴隶法典的合法暴力使白人主宰常态化；同时烟草劳动相对稳定，奴隶家庭得以繁衍，至世纪中叶本土出生的黑人已占多数。", "exp_en": "The Chesapeake shows slavery hardening from a labor system into a racial order: law, violence, and demography fused to make bondage hereditary.", "exp_zh": "切萨皮克展示了奴隶制如何从劳工制度硬化为种族秩序：法律、暴力与人口结构融合，使奴役成为世袭。", "page": 96, "topic_es": "La esclavitud en Chesapeake: la revolución del tabaco y los códigos raciales", "what_es": "Después de la Rebelión de Bacon y del fin del monopolio de la Royal African Company en 1698, los plantadores de Chesapeake lideraron una 'revolución del tabaco', comprando más africanos hasta que fueron el 40 por ciento de la población hacia 1740; Virginia definió la esclavitud en términos raciales — los africanos no cristianos 'serán considerados y serán esclavos' — y en 1669 decretó que un amo que matara a un esclavo mientras lo 'corregía' no podía ser acusado de delito grave.", "cause_es": "La expansión del comercio británico de esclavos hizo a los africanos más baratos y disponibles justo cuando los plantadores querían una fuerza laboral controlable y de por vida para reemplazar a los sirvientes contratados después de la Rebelión de Bacon.", "sig_es": "La esclavitud se convirtió en una institución central, definida racialmente, en Chesapeake, y la violencia legal de los códigos de esclavos normalizó el dominio blanco — aun cuando la mano de obra más estable del tabaco permitió que las familias esclavizadas crecieran y surgiera una mayoría negra nacida en América hacia mediados de siglo.", "exp_es": "Chesapeake muestra la esclavitud endureciéndose de un sistema laboral a un orden racial: ley, violencia y demografía se fusionaron para hacer hereditaria la servidumbre.", "who_es": []}, {"id": "p2-016", "period": 2, "topic_en": "Rice slavery in South Carolina and the black majority", "topic_zh": "南卡罗来纳的水稻奴隶制与黑人多数", "year": null, "year_text": "after 1700", "who": [], "who_zh": [], "what_en": "After 1700 South Carolina planters planted rice for southern Europe, and rice production quintupled between 1720 and 1750; by 1710 Africans were a majority of the colony's population — up to 80 percent in rice-growing areas — working ankle-deep in malarial swamps to build irrigation works.", "what_zh": "1700年后南卡种植园主为南欧市场种植水稻，1720至1750年产量增长五倍；1710年非洲人已占殖民地人口多数——水稻区高达80%——在疟疾肆虐的沼泽中齐踝劳作、修建灌溉工程。", "cause_en": "Rice was in great demand in southern Europe, and planters imported thousands of Africans — some from rice-growing societies who knew the crop — to do the dangerous, exhausting labor whites would not.", "cause_zh": "水稻在南欧需求旺盛，种植园主进口数千非洲人——其中一些来自水稻种植社会、懂得种稻——来从事白人不愿干的危险繁重劳作。", "sig_en": "The black majority allowed a strongly African-influenced language and culture to develop, but the brutal regime of disease and overwork meant constant 're-Africanization' through new imports and set the stage for the Stono Rebellion.", "sig_zh": "黑人多数使浓厚的非洲影响语言文化得以发展，但疾病与过度劳作的残酷制度意味着靠新进口不断“再非洲化”，也为斯托诺起义埋下伏笔。", "exp_en": "Carolina rice made slavery most extreme on the mainland: extraordinary profits bought with extraordinary death, and an African majority that whites lived in fear of.", "exp_zh": "卡罗来纳水稻使本土奴隶制走向极端：以惊人死亡换取惊人利润，非洲裔多数让白人终日恐惧。", "page": 96, "topic_es": "La esclavitud del arroz en South Carolina y la mayoría negra", "what_es": "Después de 1700 los plantadores de South Carolina sembraron arroz para el sur de Europa, y la producción de arroz se quintuplicó entre 1720 y 1750; hacia 1710 los africanos eran mayoría de la población de la colonia — hasta el 80 por ciento en las zonas arroceras — trabajando con el agua hasta los tobillos en pantanos maláricos para construir obras de riego.", "cause_es": "El arroz tenía gran demanda en el sur de Europa, y los plantadores importaron miles de africanos — algunos de sociedades arroceras que conocían el cultivo — para el trabajo peligroso y agotador que los blancos no harían.", "sig_es": "La mayoría negra permitió que se desarrollara un lenguaje y una cultura de fuerte influencia africana, pero el régimen brutal de enfermedad y exceso de trabajo significó una constante 'reafricanización' mediante nuevas importaciones y preparó el escenario para la Rebelión de Stono.", "exp_es": "El arroz de Carolina hizo la esclavitud más extrema del continente: ganancias extraordinarias compradas con muerte extraordinaria, y una mayoría africana a la que los blancos temían.", "who_es": []}, {"id": "p2-017", "period": 2, "topic_en": "Emergence of an African American community", "topic_zh": "非洲裔美国人社群的形成", "year": null, "year_text": "1720s-1750s", "who": [], "who_zh": [], "what_en": "Thrown together from many African peoples, enslaved people gradually forged families, kin networks, and culture — African instruments like the molo (forerunner of the banjo), spiritual practices like obeah, and, in the Chesapeake after 1725, strong nuclear families — creating, as one observer put it, 'a Nation within a Nation.'", "what_zh": "来自众多非洲族群的奴隶逐渐锻造出家庭、亲缘网络与文化——非洲乐器“莫洛”（班卓琴前身）、奥贝亚等灵性习俗，在切萨皮克1725年后形成稳固核心家庭——正如一位观察者所言，形成了“国中之国”。", "cause_en": "A more balanced sex ratio after the 1720s and the limited freedoms owners conceded let slaves build precarious family lives; in South Carolina the high death rate undermined families, but in the Chesapeake kin groups took root.", "cause_zh": "1720年代后性别比趋于平衡，加上主人让渡的有限自由，使奴隶得以建立脆弱的家庭生活；南卡高死亡率瓦解家庭，切萨皮克的亲缘群体却扎下根来。", "sig_en": "A distinct African American culture emerged that preserved African heritage while adapting to American slavery — the foundation of black community life for centuries to come.", "sig_zh": "独特的非洲裔美国文化就此形成，既保留非洲传统又适应美洲奴隶制，成为此后数百年黑人社群生活的基础。", "exp_en": "Out of the slave trade's chaos, enslaved people rebuilt community: family names, music, and faith became instruments of survival and identity.", "exp_zh": "奴隶们在贩奴贸易的废墟上重建社群：家族姓氏、音乐与信仰成为生存与认同的工具。", "page": 97, "topic_es": "Surgimiento de una comunidad afroamericana", "what_es": "Reunidos a la fuerza desde muchos pueblos africanos, los esclavizados forjaron gradualmente familias, redes de parentesco y cultura — instrumentos africanos como el molo (precursor del banjo), prácticas espirituales como el obeah y, en Chesapeake después de 1725, fuertes familias nucleares — creando, como dijo un observador, 'una Nación dentro de una Nación'.", "cause_es": "Una proporción de sexos más equilibrada después de la década de 1720 y las limitadas libertades que los amos concedieron permitieron a los esclavos construir precarias vidas familiares; en South Carolina la alta mortalidad socavó las familias, pero en Chesapeake los grupos de parentesco echaron raíces.", "sig_es": "Surgió una cultura afroamericana distintiva que preservó la herencia africana adaptándose a la esclavitud americana — el fundamento de la vida comunitaria negra en los siglos venideros.", "exp_es": "Del caos del comercio de esclavos, los esclavizados reconstruyeron la comunidad: apellidos, música y fe se volvieron instrumentos de supervivencia e identidad.", "who_es": []}, {"id": "p2-018", "period": 2, "topic_en": "Stono Rebellion (1739)", "topic_zh": "斯托诺起义（1739）", "year": 1739, "year_text": "September 1739", "who": [], "who_zh": [], "what_en": "In September 1739, 75 Africans rose near the Stono River in South Carolina — instigated by Spanish Florida's promise of freedom to fugitives — and marched toward Florida 'with Colours displayed and two Drums beating' before a mounted militia killed 44 of them and crushed the revolt.", "what_zh": "1739年9月，75名非洲人在南卡罗来纳斯托诺河附近起义——受西属佛罗里达向逃奴承诺自由的煽动——“军旗招展、双鼓齐鸣”向佛罗里达进军，随即被骑马民兵击杀44人、镇压。", "cause_en": "War between England and Spain broke out in September 1739, and the Catholic governor of Spanish Florida had been luring Carolina slaves with promises of freedom; by February at least 69 had already escaped to St. Augustine.", "cause_zh": "1739年9月英西开战，西属佛罗里达的天主教总督以自由为饵引诱卡罗来纳奴隶；到当年2月已有至少69人逃往圣奥古斯丁。", "sig_en": "The largest slave uprising in the mainland colonies illustrated the impossibility of successful revolt under plantation slavery; frightened South Carolinians cut slave imports and tightened plantation discipline.", "sig_zh": "这是本土殖民地最大规模的奴隶起义，也证明了在种植园奴隶制下成功起义几乎不可能；惊恐的南卡罗来纳人削减奴隶进口、收紧种植园纪律。", "exp_en": "Stono was both the high-water mark of mainland slave resistance and the proof of its futility: courage and military skill shattered against the planters' preponderance of force.", "exp_zh": "斯托诺既是本土奴隶反抗的高峰，也是其徒劳的证明：勇气与军事技能在种植园主的绝对武力面前粉碎。", "page": 101, "topic_es": "Rebelión de Stono (1739)", "what_es": "En septiembre de 1739, 75 africanos se levantaron cerca del río Stono en South Carolina — instigados por la promesa de libertad de la Florida española a los fugitivos — y marcharon hacia Florida 'con banderas desplegadas y dos tambores sonando' antes de que una milicia montada matara a 44 de ellos y aplastara la revuelta.", "cause_es": "La guerra entre Inglaterra y España estalló en septiembre de 1739, y el gobernador católico de la Florida española venía atrayendo esclavos de Carolina con promesas de libertad; para febrero al menos 69 ya habían escapado a St. Augustine.", "sig_es": "El mayor levantamiento de esclavos en las colonias continentales ilustró la imposibilidad de una revuelta exitosa bajo la esclavitud de plantación; los asustados habitantes de South Carolina recortaron las importaciones de esclavos y endurecieron la disciplina de las plantaciones.", "exp_es": "Stono fue a la vez el punto culminante de la resistencia esclava continental y la prueba de su futilidad: coraje y habilidad militar destrozados contra la preponderancia de fuerza de los plantadores.", "who_es": [], "img": {"file": "img:f1_2185", "credit": "图源：Henretta《America's History》第8版 p.101"}}, {"id": "p2-019", "period": 2, "topic_en": "Southern gentry and gentility (William Byrd II)", "topic_zh": "南方乡绅与绅士风度（小威廉·伯德）", "year": null, "year_text": "early-mid 1700s", "who": ["William Byrd II"], "who_zh": ["小威廉·伯德"], "what_en": "Wealthy Chesapeake and Carolina planters like William Byrd II (1674-1744) used slave profits to build brick mansions, educate sons in London, and cultivate gentility — a refined, elaborate lifestyle modeled on the English aristocracy — while using violence to exploit enslaved blacks and bribing poor whites with votes, rum, and offices.", "what_zh": "以小威廉·伯德（1674–1744）为代表的切萨皮克与卡罗来纳富裕种植园主，用奴隶利润建造砖石豪宅、送儿子去伦敦受教育，培养“绅士风度”——模仿英国贵族的精致生活方式——同时以暴力剥削黑奴，以选票、朗姆酒和官职收买贫穷白人。", "cause_en": "Slave-generated wealth and the desire to overcome their inferior 'colonial' status — Byrd himself was shunned in England as a 'colonial' — pushed planters to emulate the English gentry and to secure yeoman loyalty against uprisings like Bacon's Rebellion.", "cause_zh": "奴隶创造的财富与摆脱低人一等“殖民地人”身份的渴望——伯德本人在英国就被当作“殖民地人”冷落——促使种植园主模仿英国乡绅，并收买自耕农以防培根起义重演。", "sig_en": "The gentry strategy worked: lowering the head tax (45 to 5 pounds of tobacco, 1675-1750) and opening the vote to poor whites bought deference, letting planter families like the Carters and Lees dominate the House of Burgesses and limit royal governors.", "sig_zh": "乡绅策略奏效：降低人头税（1675–1750年从45磅烟草降到5磅）、向贫穷白人开放投票权换来顺从，使卡特、李等家族主导众议院、压制王室总督。", "exp_en": "Gentility was power made beautiful: a cultural performance that set planters apart from common whites while their political bribes kept those same whites loyal.", "exp_zh": "绅士风度是被美化了的权力：一种文化表演，既把种植园主与平民白人区分开来，又以政治收买让这些白人保持忠诚。", "page": 102, "topic_es": "La aristocracia sureña y la gentileza (William Byrd II)", "what_es": "Ricos plantadores de Chesapeake y Carolina como William Byrd II (1674-1744) usaron las ganancias de la esclavitud para construir mansiones de ladrillo, educar a sus hijos en Londres y cultivar la gentileza — un estilo de vida refinado y elaborado modelado sobre la aristocracia inglesa — mientras usaban la violencia para explotar a los negros esclavizados y sobornaban a los blancos pobres con votos, ron y cargos.", "cause_es": "La riqueza generada por la esclavitud y el deseo de superar su inferior estatus 'colonial' — al propio Byrd lo despreciaban en Inglaterra como 'colonial' — empujaron a los plantadores a emular a la aristocracia inglesa y a asegurar la lealtad de los yeomen frente a levantamientos como la Rebelión de Bacon.", "sig_es": "La estrategia de la aristocracia funcionó: bajar el impuesto de capitación (de 45 a 5 libras de tabaco, 1675-1750) y abrir el voto a los blancos pobres compró deferencia, permitiendo a familias plantadoras como los Carter y los Lee dominar la House of Burgesses y limitar a los gobernadores reales.", "exp_es": "La gentileza era el poder hecho belleza: una actuación cultural que distinguía a los plantadores de los blancos comunes mientras sus sobornos políticos mantenían leales a esos mismos blancos.", "who_es": ["William Byrd II"]}, {"id": "p2-020", "period": 2, "topic_en": "Northern maritime economy and American merchants", "topic_zh": "北方海运经济与美洲商人", "year": null, "year_text": "1640s-1750s", "who": [], "who_zh": [], "what_en": "New England and Middle Atlantic farmers supplied the sugar islands with bread, lumber, fish, and meat, while mainland distilleries turned West Indian molasses into rum (over 2.5 million gallons in Massachusetts by the 1770s); by 1750 American-born merchants controlled 95 percent of mainland-West Indies commerce, and port cities like Philadelphia boomed.", "what_zh": "新英格兰与中大西洋农民向糖岛供应面包、木材、鱼肉，本土蒸馏厂把西印度糖蜜酿成朗姆酒（1770年代马萨诸塞年产超250万加仑）；1750年本土出生的商人已控制本土—西印度贸易的95%，费城等港口城市蓬勃发展。", "cause_en": "West Indian planters found sugar so profitable they preferred buying provisions 'at very deare rates' to growing food, and mainland farmers and merchants rushed to fill the demand.", "cause_zh": "西印度种植园主觉得种糖利润太高，宁愿“高价买粮”也不自己种粮食，本土农民与商人蜂拥填补这一需求。", "sig_en": "The provision trade created the first American merchant fortunes and urban industries — shipbuilding, sugar refineries, fisheries — and made the northern colonies economically interdependent with the slave-based South Atlantic System.", "sig_zh": "粮食贸易造就了第一批美洲商业巨富与城市工业——造船、制糖、渔业——使北方殖民地在经济上与基于奴隶制的南大西洋体系相互依存。", "exp_en": "The northern maritime economy shows the whole empire was one machine: New England cod and Pennsylvania wheat fed the slaves who grew the sugar that enriched London.", "exp_zh": "北方海运经济表明整个帝国是一台机器：新英格兰鳕鱼和宾夕法尼亚小麦喂养着种糖的奴隶，糖又使伦敦暴富。", "page": 103, "topic_es": "La economía marítima del norte y los comerciantes americanos", "what_es": "Los agricultores de New England y del Atlántico Medio abastecían a las islas azucareras con pan, madera, pescado y carne, mientras las destilerías continentales convertían la melaza antillana en ron (más de 2,5 millones de galones en Massachusetts hacia la década de 1770); hacia 1750 los comerciantes nacidos en América controlaban el 95 por ciento del comercio continental-antillano, y ciudades portuarias como Philadelphia prosperaban.", "cause_es": "Los plantadores antillanos encontraban el azúcar tan rentable que preferían comprar provisiones 'a precios muy caros' antes que cultivar alimentos, y los agricultores y comerciantes continentales se apresuraron a satisfacer la demanda.", "sig_es": "El comercio de provisiones creó las primeras fortunas mercantiles americanas e industrias urbanas — construcción naval, refinerías de azúcar, pesquerías — e hizo a las colonias del norte económicamente interdependientes con el Sistema Atlántico Sur basado en la esclavitud.", "exp_es": "La economía marítima del norte muestra que todo el imperio era una sola máquina: el bacalao de New England y el trigo de Pennsylvania alimentaban a los esclavos que cultivaban el azúcar que enriquecía a Londres.", "who_es": []}, {"id": "p2-021", "period": 2, "topic_en": "Rise of colonial assemblies", "topic_zh": "殖民地议会的崛起", "year": null, "year_text": "1700-1760", "who": ["Alexander Spotswood"], "who_zh": ["亚历山大·斯波茨伍德"], "what_en": "Between 1700 and 1760 colonial assemblies expanded their authority piecemeal: they withheld governors' permanent salaries, seized control of taxation and appointments, and defied imperial instructions — as Virginia's governor Alexander Spotswood furiously reported when the Burgesses, elected on a half-acre franchise, blocked his reforms.", "what_zh": "1700至1760年间，殖民地议会逐步扩张权力：扣发总督固定薪俸、夺取征税与任命权、违抗帝国指令——弗吉尼亚总督斯波茨伍德愤怒上书时，半英亩选举权选出的众议院正阻挠其改革。", "cause_en": "Salutary neglect left royal bureaucrats too weak to stop them, and governors' patronage appointments filled offices with do-nothing political hacks, while popular crowd actions backed the assemblies against imperial officials.", "cause_zh": "“有益的忽视”使王室官僚无力制止，总督的恩宠任命又把官职塞满无所事事的政治混子，民众的群体行动则在背后支持议会对抗帝国官员。", "sig_en": "The assemblies' piecemeal victories unintentionally laid the foundation for the independence movement: colonial legislators learned to wield power against the crown long before 1776.", "sig_zh": "议会一次次不起眼的胜利无意中为独立运动奠基：殖民地立法者在1776年之前很久就学会了如何与王权较量。", "src": {"text": "so long as half an Acre of Land (which is of small value in this Country) qualifys a man to be an Elector, the meaner sort of People will ever carry ye Elections", "attr": "Alexander Spotswood to Secretary James Stanhope, July 15, 1715"}, "exp_en": "The rise of the assemblies was the quiet revolution before the Revolution: power shifted from appointed governors to elected legislators one salary fight at a time.", "exp_zh": "议会的崛起是革命之前的静悄悄革命：权力一次薪俸之争、一次薪俸之争地从任命总督转移到民选立法者手中。", "page": 105, "topic_es": "El ascenso de las asambleas coloniales", "what_es": "Entre 1700 y 1760 las asambleas coloniales ampliaron su autoridad poco a poco: retenían los salarios permanentes de los gobernadores, se apoderaban del control de impuestos y nombramientos, y desafiaban las instrucciones imperiales — como informó furioso el gobernador de Virginia Alexander Spotswood cuando los Burgesses, elegidos con un sufragio de medio acre, bloquearon sus reformas.", "cause_es": "La negligencia saludable dejó a los burócratas reales demasiado débiles para detenerlas, y los nombramientos clientelares de los gobernadores llenaron los cargos de enchufados inútiles, mientras las acciones populares callejeras respaldaban a las asambleas contra los funcionarios imperiales.", "sig_es": "Las victorias graduales de las asambleas sentaron sin querer las bases del movimiento independentista: los legisladores coloniales aprendieron a ejercer el poder contra la corona mucho antes de 1776.", "exp_es": "El ascenso de las asambleas fue la revolución silenciosa antes de la Revolución: el poder pasó de los gobernadores designados a los legisladores electos, una lucha salarial a la vez.", "who_es": ["Alexander Spotswood"], "img": {"file": "img:f1_2198", "credit": "图源：Henretta《America's History》第8版 p.105"}}, {"id": "p2-022", "period": 2, "topic_en": "Salutary neglect (1714-1750)", "topic_zh": "“有益的忽视”（1714–1750）", "year": 1714, "year_text": "1714-1750", "who": ["Robert Walpole", "George I", "George II", "Edmund Burke"], "who_zh": ["罗伯特·沃波尔", "乔治一世", "乔治二世", "埃德蒙·伯克"], "what_en": "Under George I and II, royal bureaucrats relaxed supervision of internal colonial affairs — a policy Edmund Burke later praised in 1775 as 'salutary neglect' — a by-product of Robert Walpole's patronage politics (Walpole led the Commons, 1720-1742), which filled the Board of Trade with do-nothing appointees.", "what_zh": "乔治一世、二世时期，王室官僚放松了对殖民地内部事务的监督——埃德蒙·伯克1775年称之为“有益的忽视”——这是罗伯特·沃波尔恩宠政治（1720–1742年领导下议院）的副产品，贸易委员会被塞满无所事事的任命者。", "cause_en": "Ministers were pleased with the wealth from the slave, sugar, rice, and tobacco trades, and Walpole's motto 'Let sleeping dogs lie' made non-interference politically convenient.", "cause_zh": "大臣们对奴隶、糖、稻米、烟草贸易带来的财富心满意足，沃波尔“让睡着的狗继续睡”的座右铭使不干预在政治上很便利。", "sig_en": "Salutary neglect allowed the assemblies to grow powerful and colonial societies to develop a life of their own — but when new leaders after 1749 vowed to replace it with rigorous imperial control, the colonists were primed to resist.", "sig_zh": "“有益的忽视”让议会坐大、殖民地社会长出自己的生命；但1749年后新领导人发誓以严格帝国管控取代它时，殖民者已做好反抗准备。", "why_term": "salutary neglect", "why_term_q": "1714–1750年英国对殖民地内部事务放松监督的政策被称为______。", "exp_en": "Salutary neglect was neglect with consequences: thirty-five years of looking away taught Americans to govern themselves — and to resent being governed again.", "exp_zh": "“有益的忽视”是有后果的忽视：三十五年的睁一只眼闭一只眼教会了美国人自治——也教会了他们痛恨再度被统治。", "page": 106, "topic_es": "Negligencia saludable (1714-1750)", "what_es": "Bajo George I y II, los burócratas reales relajaron la supervisión de los asuntos internos coloniales — una política que Edmund Burke elogiaría en 1775 como 'salutary neglect' — subproducto de la política clientelar de Robert Walpole (Walpole lideró los Comunes, 1720-1742), que llenó el Board of Trade de designados inútiles.", "cause_es": "Los ministros estaban satisfechos con la riqueza del comercio de esclavos, azúcar, arroz y tabaco, y el lema de Walpole 'deja dormir a los perros' hacía políticamente conveniente la no intervención.", "sig_es": "La negligencia saludable permitió que las asambleas se fortalecieran y que las sociedades coloniales desarrollaran vida propia — pero cuando nuevos líderes después de 1749 juraron reemplazarla con un riguroso control imperial, los colonos estaban listos para resistir.", "exp_es": "La negligencia saludable fue negligencia con consecuencias: treinta y cinco años de mirar hacia otro lado enseñaron a los americanos a gobernarse solos — y a resentir que los gobernaran de nuevo.", "who_es": ["Robert Walpole", "George I", "George II", "Edmund Burke"], "why_term_q_es": "La política de supervisión relajada de los asuntos internos coloniales aplicada por Inglaterra entre 1714 y 1750 se denomina ______."}, {"id": "p2-023", "period": 2, "topic_en": "Mercantilist restrictions: Hat, Molasses, and Iron Acts", "topic_zh": "重商主义限制：《帽子法》《糖蜜法》《铁法》", "year": 1732, "year_text": "1732-1750", "who": [], "who_zh": [], "what_en": "To protect British manufacturers and West Indian planters, Parliament passed the Hat Act (1732) and Iron Act (1750) limiting colonial manufacturing, and the Molasses Act (1733), which put a prohibitive tariff on French molasses to protect the British sugar lobby — colonists simply smuggled French molasses by bribing customs officials.", "what_zh": "为保护英国制造商与西印度种植园主，议会通过《帽子法》（1732）与《铁法》（1750）限制殖民地制造业，以及《糖蜜法》（1733）对法国糖蜜征收高到禁绝的关税以保护英国糖业游说集团——殖民者则贿赂海关官员继续走私法国糖蜜。", "cause_en": "American merchants were ignoring Britain's rivalry with France and buying cheap French molasses for their rum distilleries, while colonial manufacturing threatened British producers; the West Indian sugar lobby demanded protection.", "cause_zh": "美洲商人不顾英法竞争，大量购买廉价法国糖蜜酿朗姆酒，殖民地制造业又威胁英国生产商；西印度糖业游说集团要求保护。", "sig_en": "The acts were 'extensively violated,' proving that mercantilist law could not restrain a maturing colonial economy — and each evasion deepened colonial contempt for Parliament's authority.", "sig_zh": "这些法案被“普遍违反”，证明重商主义法律管不住成熟的殖民地经济——每一次规避都加深了殖民者对议会权威的蔑视。", "exp_en": "The Hat, Molasses, and Iron Acts were mercantilism at its most grasping — and its most futile, since American merchants controlled three-quarters of the transatlantic trade they were meant to restrain.", "exp_zh": "《帽子法》《糖蜜法》《铁法》是重商主义最贪婪也最徒劳的体现——美洲商人已控制了这些法案意在管制的跨大西洋贸易的四分之三。", "page": 107, "topic_es": "Restricciones mercantilistas: Hat Act, Molasses Act e Iron Act", "what_es": "Para proteger a los manufactureros británicos y a los plantadores antillanos, el Parlamento aprobó la Hat Act (1732) y la Iron Act (1750), que limitaban la manufactura colonial, y la Molasses Act (1733), que impuso un arancel prohibitivo a la melaza francesa para proteger al lobby azucarero británico — los colonos simplemente contrabandeaban melaza francesa sobornando a los funcionarios de aduanas.", "cause_es": "Los comerciantes americanos ignoraban la rivalidad de Gran Bretaña con Francia y compraban melaza francesa barata para sus destilerías de ron, mientras la manufactura colonial amenazaba a los productores británicos; el lobby azucarero antillano exigía protección.", "sig_es": "Las leyes fueron 'ampliamente violadas', probando que la ley mercantilista no podía refrenar una economía colonial en maduración — y cada evasión profundizaba el desprecio colonial por la autoridad del Parlamento.", "exp_es": "Las Hat, Molasses e Iron Acts fueron el mercantilismo en su forma más codiciosa — y más fútil, pues los comerciantes americanos controlaban tres cuartas partes del comercio transatlántico que se suponía debían refrenar.", "who_es": [], "img": {"file": "img:f1_2206", "credit": "图源：Henretta《America's History》第8版 p.107"}}, {"id": "p2-024", "period": 2, "topic_en": "Land banks and the Currency Act (1751)", "topic_zh": "土地银行与《货币法》（1751）", "year": 1751, "year_text": "1751", "who": [], "who_zh": [], "what_en": "To relieve the chronic shortage of money, ten colonial assemblies created public land banks that lent paper money to farmers against their land; after Rhode Island flooded the market with devalued notes, Parliament's Currency Act of 1751 barred New England colonies from new land banks and from using public paper money to pay private debts.", "what_zh": "为缓解长期货币短缺，十个殖民地议会设立公立土地银行，以土地为抵押向农民发放纸币；罗得岛滥发贬值纸币后，议会1751年《货币法》禁止新英格兰殖民地设立新土地银行、禁止用公发纸币偿还私人债务。", "cause_en": "Payments for British manufactures drained gold and silver from the colonies, making it hard for Americans to borrow or trade among themselves; land banks were the assemblies' homegrown solution.", "cause_zh": "购买英国制成品的付款抽干了殖民地的金银，使美国人难以借贷或内部交易；土地银行是议会自创的解决办法。", "sig_en": "The Currency Act was a direct clash between colonial economic self-help and imperial control of money — one of the conflicts that angered a new generation of English leaders and foreshadowed the imperial crisis.", "sig_zh": "《货币法》是殖民地经济自救与帝国货币管控的直接冲突，是激怒新一代英国领导人、预示帝国危机的矛盾之一。", "exp_en": "The land-bank fight shows the assemblies acting like real governments — issuing currency — and Parliament slapping them down, a rehearsal for the larger sovereignty battles to come.", "exp_zh": "土地银行之争显示议会已像真正的政府一样行事——发行货币——而议会将其打压，这是更大主权之争的预演。", "page": 110, "topic_es": "Bancos de tierras y la Currency Act (1751)", "what_es": "Para aliviar la crónica escasez de dinero, diez asambleas coloniales crearon bancos públicos de tierras que prestaban papel moneda a los agricultores contra sus tierras; después de que Rhode Island inundara el mercado con billetes devaluados, la Currency Act del Parlamento de 1751 prohibió a las colonias de New England crear nuevos bancos de tierras y usar papel moneda público para pagar deudas privadas.", "cause_es": "Los pagos por manufacturas británicas drenaban el oro y la plata de las colonias, dificultando a los americanos pedir prestado o comerciar entre sí; los bancos de tierras fueron la solución casera de las asambleas.", "sig_es": "La Currency Act fue un choque directo entre la autoayuda económica colonial y el control imperial del dinero — uno de los conflictos que enfureció a una nueva generación de líderes ingleses y presagió la crisis imperial.", "exp_es": "La lucha de los bancos de tierras muestra a las asambleas actuando como verdaderos gobiernos — emitiendo moneda — y al Parlamento dándoles una bofetada, un ensayo de las batallas mayores por la soberanía que vendrían.", "who_es": [], "img": {"file": "img:f1_2212", "credit": "图源：Henretta《America's History》第8版 p.110"}}, {"id": "p2-025", "period": 2, "topic_en": "Founding of Georgia (1732) and the War of Jenkins's Ear", "topic_zh": "佐治亚的建立（1732）与詹金斯之耳战争", "year": 1732, "year_text": "1732-1748", "who": ["Robert Walpole"], "who_zh": ["罗伯特·沃波尔"], "what_en": "Parliament chartered Georgia in 1732 — Walpole subsidized it to shield South Carolina's rice colony from Spain — but the expansion provoked Spain, whose coast guard mutilated Captain Robert Jenkins; Walpole declared the War of Jenkins's Ear in 1739, a fiasco crowned by the failed 1741 attack on Cartagena, where 20,000 British and 2,500 colonial troops died mostly of disease.", "what_zh": "议会1732年特许建立佐治亚——沃波尔资助它是为保护南卡水稻殖民地免受西班牙威胁——但扩张激怒西班牙，其海岸警卫队割掉了詹金斯船长的耳朵；沃波尔1739年宣战，詹金斯之耳战争以惨败告终，1741年进攻卡塔赫纳失败，2万英军与2500殖民地士兵多死于疾病。", "cause_en": "Walpole wanted a buffer for valuable South Carolina; Spain answered British commercial expansion by seizing smugglers, and parliamentary pressure forced Walpole into a war he did not want.", "cause_zh": "沃波尔想要为宝贵的南卡罗来纳建立缓冲；西班牙以扣押走私船回应英国商业扩张，议会压力迫使沃波尔打了一场他并不想打的仗。", "sig_en": "The war merged into the War of the Austrian Succession, in which New Englanders captured Louisbourg in 1745 — only for the Treaty of Aix-la-Chapelle (1748) to hand it back to France, teaching colonial leaders that London would act in its own interests, not theirs.", "sig_zh": "战争并入奥地利王位继承战争，新英格兰人1745年攻占路易斯堡——但1748年《亚琛条约》又把它还给法国，让殖民地领袖明白伦敦只会为自身利益行事。", "exp_en": "Georgia began as a philanthropic refuge and became a tripwire: its founding shows how colonial expansion could drag a reluctant empire into war — and how little the empire then valued colonial sacrifices.", "exp_zh": "佐治亚始于慈善避难所，终成导火索：它的建立显示殖民地扩张如何把不情愿的帝国拖入战争，也显示帝国多么轻视殖民者的牺牲。", "page": 106, "topic_es": "Fundación de Georgia (1732) y la Guerra de la Oreja de Jenkins", "what_es": "El Parlamento otorgó la carta de Georgia en 1732 — Walpole la subsidió para proteger la colonia arrocera de South Carolina frente a España — pero la expansión provocó a España, cuya guardacostas mutiló al capitán Robert Jenkins; Walpole declaró la Guerra de la Oreja de Jenkins en 1739, un fiasco coronado por el fallido ataque de 1741 a Cartagena, donde 20.000 británicos y 2.500 tropas coloniales murieron mayormente de enfermedades.", "cause_es": "Walpole quería un amortiguador para la valiosa South Carolina; España respondió a la expansión comercial británica capturando contrabandistas, y la presión parlamentaria forzó a Walpole a una guerra que no deseaba.", "sig_es": "La guerra se fusionó en la Guerra de Sucesión Austriaca, en la que los habitantes de New England capturaron Louisbourg en 1745 — solo para que el Tratado de Aix-la-Chapelle (1748) se la devolviera a Francia, enseñando a los líderes coloniales que Londres actuaría en su propio interés, no en el de ellos.", "exp_es": "Georgia comenzó como refugio filantrópico y se volvió un detonante: su fundación muestra cómo la expansión colonial podía arrastrar a un imperio renuente a la guerra — y cuán poco valoraba luego el imperio los sacrificios coloniales.", "who_es": ["Robert Walpole"]}, {"id": "p2-026", "period": 2, "topic_en": "Migration: Scots-Irish and Germans transform the colonies", "topic_zh": "移民潮：苏格兰-爱尔兰人与德意志人重塑殖民地", "year": 1736, "year_text": "1720s-1760s", "who": [], "who_zh": [], "what_en": "Some 300,000 European migrants — chiefly Highland Scots, Scots-Irish, and Germans, like Alexander MacAllister, who left Scotland for North Carolina in 1736 calling it 'the best poor man's country' — helped swell the mainland population from 400,000 in 1720 to almost 2 million by 1765.", "what_zh": "约30万欧洲移民——主要是高地苏格兰人、苏格兰-爱尔兰人和德意志人，如1736年离苏赴北卡罗来纳、称之为“穷人最好的国家”的亚历山大·麦卡利斯特——使本土人口从1720年的40万增至1765年的近200万。", "cause_en": "The 'hope of having land of their own & becoming independent of Landlords' pulled migrants across the Atlantic, and Penn's pamphlets promising cheap land and religious toleration advertised the colonies in Germany.", "cause_zh": "“拥有自己的土地、摆脱地主”的希望把移民拉过大西洋，佩恩承诺廉价土地与宗教宽容的小册子在德意志为殖民地做了广告。", "sig_en": "By 1775 settlers of English descent were only about 50 percent of the population; the Middle colonies became a mosaic of Scots-Irish Presbyterians, German Lutherans, Dutch Reformed, and Quakers, united on liberty of conscience but divided by mutual mistrust.", "sig_zh": "到1775年英格兰后裔仅占人口约一半；中部殖民地成为苏格兰-爱尔兰长老会、德意志路德宗、荷兰归正会、贵格会的拼图，在信仰自由上一致，在相互猜忌中分裂。", "exp_en": "This migration made British North America genuinely plural: the 'American' of 1763 was far less English than the 'American' of 1700, and diversity itself became a political fact.", "exp_zh": "这场移民潮使英属北美真正多元：1763年的“美国人”远不如1700年的“英国”，多元本身成为政治事实。", "page": 114, "topic_es": "Migración: escoceses-irlandeses y alemanes transforman las colonias", "what_es": "Unos 300.000 migrantes europeos — principalmente escoceses de las Highlands, escoceses-irlandeses y alemanes, como Alexander MacAllister, que dejó Escocia por North Carolina en 1736 llamándola 'el mejor país para el hombre pobre' — ayudaron a que la población continental pasara de 400.000 en 1720 a casi 2 millones hacia 1765.", "cause_es": "La 'esperanza de tener tierra propia y volverse independientes de los terratenientes' atrajo migrantes a través del Atlántico, y los panfletos de Penn que prometían tierra barata y tolerancia religiosa anunciaban las colonias en Alemania.", "sig_es": "Hacia 1775 los colonos de ascendencia inglesa eran solo alrededor del 50 por ciento de la población; las colonias medias se volvieron un mosaico de presbiterianos escoceses-irlandeses, luteranos alemanes, reformados holandeses y cuáqueros, unidos en la libertad de conciencia pero divididos por la desconfianza mutua.", "exp_es": "Esta migración hizo a la Norteamérica británica genuinamente plural: el 'americano' de 1763 era mucho menos inglés que el 'americano' de 1700, y la diversidad misma se volvió un hecho político.", "who_es": []}, {"id": "p2-027", "period": 2, "topic_en": "New England's freehold society in crisis", "topic_zh": "新英格兰自耕农社会的危机", "year": null, "year_text": "1700-1750", "who": [], "who_zh": [], "what_en": "New England's population doubled each generation (100,000 in 1700 to nearly 400,000 in 1750), subdividing farms to 50 acres or less so parents could endow only one child; families responded with birth control, frontier migration, potatoes and corn, a shift to livestock, and the 'household mode of production,' swapping labor and goods without cash.", "what_zh": "新英格兰人口每代翻番（1700年10万至1750年近40万），农场被分割到50英亩以下，父母只能给一个孩子置产；家庭以节育、迁往边疆、种土豆玉米、转向畜牧业和“家庭生产模式”（以物易物、无现金交换劳力货物）应对。", "cause_en": "Rapid natural increase outran the available farmland in long-settled towns, and the yeoman ideal of independent freehold farming — a 'competency' passed to children — demanded land for every son.", "cause_zh": "长期定居城镇的自然人口激增超过了可耕地，自耕农独立经营的理想——传给子女的“自足能力”——要求给每个儿子土地。", "sig_en": "The crisis eroded parental control — premarital conceptions rose from 10 percent of first births in the 1710s to over 30 percent in the 1740s — and pushed New Englanders toward the frontier, the market, and eventually new social arrangements.", "sig_zh": "危机侵蚀了父母权威——婚前受孕占头胎比例从1710年代的10%升至1740年代的30%以上——把新英格兰人推向边疆、市场，并最终推向新的社会安排。", "exp_en": "The freehold crisis shows a society straining against its own success: the Puritan family farm could not reproduce itself forever, and its adaptations quietly revolutionized New England life.", "exp_zh": "自耕农危机显示一个社会被自己的成功撑裂：清教家庭农场无法永远自我复制，其调适悄然革新了新英格兰生活。", "page": 117, "topic_es": "La sociedad de propiedad libre de New England en crisis", "what_es": "La población de New England se duplicaba cada generación (100.000 en 1700 a casi 400.000 en 1750), subdividiendo las granjas a 50 acres o menos de modo que los padres solo podían dotar a un hijo; las familias respondieron con control de natalidad, migración a la frontera, papas y maíz, un giro a la ganadería y el 'modo de producción doméstico', intercambiando trabajo y bienes sin dinero.", "cause_es": "El rápido aumento natural superó la tierra agrícola disponible en los pueblos largamente asentados, y el ideal yeoman de la granja independiente en propiedad — una 'competencia' transmitida a los hijos — exigía tierra para cada hijo varón.", "sig_es": "La crisis erosionó el control parental — las concepciones prematrimoniales subieron del 10 por ciento de los primeros nacimientos en la década de 1710 a más del 30 por ciento en la de 1740 — y empujó a los habitantes de New England hacia la frontera, el mercado y eventualmente nuevos arreglos sociales.", "exp_es": "La crisis de la propiedad libre muestra una sociedad en tensión contra su propio éxito: la granja familiar puritana no podía reproducirse para siempre, y sus adaptaciones revolucionaron silenciosamente la vida de New England.", "who_es": []}, {"id": "p2-028", "period": 2, "topic_en": "Eliza Lucas and indigo in South Carolina", "topic_zh": "伊丽莎·卢卡斯与南卡罗来纳的靛蓝", "year": 1740, "year_text": "1740-1742", "who": ["Eliza Lucas"], "who_zh": ["伊丽莎·卢卡斯"], "what_en": "At sixteen Eliza Lucas was given management of her father's three South Carolina plantations; her letters of 1740-1742 record her experiments that introduced indigo cultivation, soon the colony's second-leading cash crop.", "what_zh": "十六岁的伊丽莎·卢卡斯受命管理父亲在南卡的三座种植园；她1740–1742年的信件记录了其引种靛蓝的试验，靛蓝很快成为该殖民地第二大经济作物。", "cause_en": "Her father, lieutenant governor of Antigua, was frequently absent, and the family needed a profitable new crop beyond rice; Lucas used her education and authority to run systematic trials.", "cause_zh": "其父任安提瓜副总督常年不在家，家族需要在水稻之外寻找新的赚钱作物；卢卡斯运用学识与管家权进行系统试验。", "sig_en": "Indigo diversified South Carolina's plantation economy and, with British bounties, became a major export; Lucas's letters are rare firsthand evidence of women's managerial work in a slave society.", "sig_zh": "靛蓝使南卡种植园经济多样化，在英国补贴下成为主要出口品；卢卡斯的信件是奴隶制社会中女性管理劳动的罕见一手证据。", "exp_en": "Eliza Lucas proves that plantation innovation was not only men's work: a teenage girl's experiments reshaped a colony's economy — while depending entirely on enslaved labor.", "exp_zh": "伊丽莎·卢卡斯证明种植园创新不只是男人的事：一位少女的试验重塑了一个殖民地的经济——而这一切完全依赖被奴役的劳工。", "page": 118, "topic_es": "Eliza Lucas y el añil en South Carolina", "what_es": "A los dieciséis años a Eliza Lucas se le confió la gestión de las tres plantaciones de su padre en South Carolina; sus cartas de 1740-1742 registran sus experimentos que introdujeron el cultivo del añil, pronto el segundo cultivo comercial de la colonia.", "cause_es": "Su padre, vicegobernador de Antigua, estaba frecuentemente ausente, y la familia necesitaba un nuevo cultivo rentable más allá del arroz; Lucas usó su educación y autoridad para realizar ensayos sistemáticos.", "sig_es": "El añil diversificó la economía de plantación de South Carolina y, con las primas británicas, se volvió una exportación importante; las cartas de Lucas son rara evidencia de primera mano del trabajo gerencial de las mujeres en una sociedad esclavista.", "exp_es": "Eliza Lucas prueba que la innovación en las plantaciones no fue solo obra de hombres: los experimentos de una adolescente remodelaron la economía de una colonia — dependiendo enteramente del trabajo esclavizado.", "who_es": ["Eliza Lucas"], "img": {"file": "img:f1_2232", "credit": "图源：Henretta《America's History》第8版 p.118"}}, {"id": "p2-029", "period": 2, "topic_en": "Print revolution in the colonies", "topic_zh": "殖民地的印刷革命", "year": 1695, "year_text": "1695-1776", "who": ["Benjamin Franklin"], "who_zh": ["本杰明·富兰克林"], "what_en": "When Parliament let the Licensing Act lapse in 1695, censorship ended and printshops multiplied; the colonies got the Boston News-Letter (1704) and Franklin's Pennsylvania Gazette (1729), reaching 37 newspapers by 1776 — a world of print essential to sharing grievances and joining in common cause.", "what_zh": "1695年议会任《许可法》失效，审查终结、印刷所激增；殖民地有了《波士顿新闻信》（1704）与富兰克林的《宾夕法尼亚公报》（1729），到1776年报纸达37家——印刷世界成为传播不满、联合行动的关键。", "cause_en": "The lapse of pre-publication censorship opened the floodgates in London, and improved Atlantic shipping plus colonial prosperity carried books, pamphlets, and newspapers across the ocean.", "cause_zh": "出版前审查的取消使伦敦印刷业闸门大开，改善的大西洋航运与殖民地繁荣把书籍、小册子、报纸运过大洋。", "sig_en": "Print spread both the Enlightenment and the Great Awakening — Whitefield's journals were among Franklin's best-selling titles — and gave colonists the communications network they would use to coordinate resistance.", "sig_zh": "印刷同时传播了启蒙运动与大觉醒——怀特菲尔德的旅行日志是富兰克林最畅销的书之一——并给了殖民者日后协调反抗的通讯网络。", "exp_en": "The print revolution was the information infrastructure of colonial America: without it, neither the Awakening's revivals nor the Revolution's committees could have reached a continental audience.", "exp_zh": "印刷革命是殖民地美洲的信息基础设施：没有它，大觉醒的复兴与革命的委员会都无法触及整个大陆的受众。", "page": 127, "topic_es": "La revolución de la imprenta en las colonias", "what_es": "Cuando el Parlamento dejó caducar la Licensing Act en 1695, terminó la censura y se multiplicaron las imprentas; las colonias tuvieron el Boston News-Letter (1704) y la Pennsylvania Gazette de Franklin (1729), llegando a 37 periódicos hacia 1776 — un mundo de imprenta esencial para compartir agravios y unirse en causa común.", "cause_es": "El fin de la censura previa abrió las compuertas en Londres, y el mejorado transporte atlántico más la prosperidad colonial llevaron libros, panfletos y periódicos a través del océano.", "sig_es": "La imprenta difundió tanto la Ilustración como el Gran Despertar — los diarios de Whitefield estuvieron entre los títulos más vendidos de Franklin — y dio a los colonos la red de comunicaciones que usarían para coordinar la resistencia.", "exp_es": "La revolución de la imprenta fue la infraestructura de información de la América colonial: sin ella, ni los avivamientos del Despertar ni los comités de la Revolución habrían alcanzado una audiencia continental.", "who_es": ["Benjamin Franklin"]}, {"id": "p2-030", "period": 2, "topic_en": "Enlightenment in America: Newton, Locke, and natural rights", "topic_zh": "美洲启蒙运动：牛顿、洛克与自然权利", "year": null, "year_text": "1687-1789", "who": ["Isaac Newton", "John Locke"], "who_zh": ["艾萨克·牛顿", "约翰·洛克"], "what_en": "The scientific revolution reached America as the Enlightenment: Newton's Principia (1687) modeled a lawlike universe, and Locke's Essay Concerning Human Understanding (1690) taught that character could be changed through education and reason, advancing natural rights — including the right to self-government — and the progressive improvement of society.", "what_zh": "科学革命以启蒙运动的形式抵达美洲：牛顿《原理》（1687）树立了规律宇宙的典范，洛克《人类理解论》（1690）主张品格可通过教育与理性改变，倡导自然权利——包括自治权——与社会的渐进改良。", "cause_en": "Copernicus, Newton, and a century of empirical science undermined the old cosmos of direct divine intervention, and the print revolution carried these ideas to colonial readers.", "cause_zh": "哥白尼、牛顿与一个世纪的实证科学瓦解了神直接干预的旧宇宙观，印刷革命把这些思想带给殖民地读者。", "sig_en": "Enlightenment rationalism added a secular dimension to colonial culture and foreshadowed the republican political theory of Adams, Madison, and Jefferson — while ministers like John Wise used Locke to defend congregational self-government.", "sig_zh": "启蒙理性主义为殖民地文化增添了世俗维度，预示了亚当斯、麦迪逊、杰斐逊的共和政治理论；约翰·怀斯等牧师则用洛克为会众自治辩护。", "why_term": "natural rights", "why_term_q": "启蒙思想家主张的、包括自治权在内的个人固有权利称为______。", "exp_en": "The American Enlightenment made reason a political weapon: if the universe ran by discoverable laws, so could — and should — government.", "exp_zh": "美洲启蒙运动把理性变成政治武器：如果宇宙按可发现的规律运行，政府也能够——且应该——如此。", "page": 127, "topic_es": "La Ilustración en América: Newton, Locke y los derechos naturales", "what_es": "La revolución científica llegó a América como Ilustración: los Principia de Newton (1687) modelaron un universo regido por leyes, y el Ensayo sobre el entendimiento humano de Locke (1690) enseñó que el carácter podía cambiarse mediante la educación y la razón, promoviendo los derechos naturales — incluido el derecho al autogobierno — y el mejoramiento progresivo de la sociedad.", "cause_es": "Copérnico, Newton y un siglo de ciencia empírica socavaron el viejo cosmos de intervención divina directa, y la revolución de la imprenta llevó estas ideas a los lectores coloniales.", "sig_es": "El racionalismo ilustrado añadió una dimensión secular a la cultura colonial y presagió la teoría política republicana de Adams, Madison y Jefferson — mientras ministros como John Wise usaban a Locke para defender el autogobierno congregacional.", "exp_es": "La Ilustración americana hizo de la razón un arma política: si el universo funcionaba por leyes descubribles, el gobierno también podía — y debía — hacerlo.", "who_es": ["Isaac Newton", "John Locke"], "why_term_q_es": "Los derechos inherentes de la persona defendidos por los pensadores ilustrados, incluido el derecho al autogobierno, se denominan ______."}, {"id": "p2-031", "period": 2, "topic_en": "Benjamin Franklin and American deism", "topic_zh": "本杰明·富兰克林与美洲自然神论", "year": null, "year_text": "1729-1771", "who": ["Benjamin Franklin"], "who_zh": ["本杰明·富兰克林"], "what_en": "The exemplar of the American Enlightenment, printer Benjamin Franklin founded the Pennsylvania Gazette (1729) and the American Philosophical Society (1743), popularized practical reason in Poor Richard's Almanack (1732-1757), and — as his Autobiography (1771) records — 'soon became a thorough Deist,' believing a Supreme Being created the world but did not intervene in it.", "what_zh": "美洲启蒙运动的典范、印刷商本杰明·富兰克林创办《宾夕法尼亚公报》（1729）与美国哲学会（1743），在《穷理查年鉴》（1732–1757）中普及实用理性，并如其《自传》（1771）所记“很快成为彻底的自然神论者”，相信最高存在创造世界后不再干预。", "cause_en": "Raised by devout Calvinists but educated through voracious reading in the print revolution's flood of books, Franklin doubted revealed religion and embraced 'natural reason' as his moral guide.", "cause_zh": "富兰克林由虔诚加尔文主义者养大，却在印刷革命的书海中博览群书，怀疑启示宗教，奉“自然理性”为道德指南。", "sig_en": "Franklin embodied the Enlightenment's practical spirit — bifocals, the Franklin stove, the lightning rod — and his deism modeled a rational, tolerant faith that influenced revolutionary leaders like Jefferson.", "sig_zh": "富兰克林体现了启蒙运动的实用精神——双光眼镜、富兰克林炉、避雷针——其自然神论为杰斐逊等革命领袖树立了理性宽容的信仰样板。", "src": {"text": "I soon became a thorough Deist. . . . I grew convinc'd that Truth, Sincerity & Integrity in Dealings between Man & Man, were of the utmost Importance to the Felicity of Life", "attr": "Benjamin Franklin, The Autobiography (1771)"}, "exp_en": "Franklin turned Enlightenment ideas into American common sense: virtue as practice, knowledge as useful, and religion as morality without miracles.", "exp_zh": "富兰克林把启蒙思想变成美国常识：德行即实践，知识要有用，宗教是无神迹的道德。", "page": 128, "topic_es": "Benjamin Franklin y el deísmo americano", "what_es": "Exponente de la Ilustración americana, el impresor Benjamin Franklin fundó la Pennsylvania Gazette (1729) y la American Philosophical Society (1743), popularizó la razón práctica en el Poor Richard's Almanack (1732-1757) y — como registra su Autobiography (1771) — 'pronto se volvió un deísta convencido', creyendo que un Ser Supremo creó el mundo pero no intervenía en él.", "cause_es": "Criado por devotos calvinistas pero educado mediante una lectura voraz en la inundación de libros de la revolución de la imprenta, Franklin dudó de la religión revelada y abrazó la 'razón natural' como su guía moral.", "sig_es": "Franklin encarnó el espíritu práctico de la Ilustración — bifocales, la estufa Franklin, el pararrayos — y su deísmo modeló una fe racional y tolerante que influyó en líderes revolucionarios como Jefferson.", "exp_es": "Franklin convirtió las ideas ilustradas en sentido común americano: la virtud como práctica, el conocimiento como útil y la religión como moralidad sin milagros.", "who_es": ["Benjamin Franklin"], "img": {"file": "img:f1_2277", "credit": "图源：Henretta《America's History》第8版 p.128"}}, {"id": "p2-032", "period": 2, "topic_en": "Pietism in the Middle colonies", "topic_zh": "中部殖民地的虔敬主义", "year": null, "year_text": "1700s-1730s", "who": ["Theodore Jacob Frelinghuysen", "William Tennent", "Gilbert Tennent"], "who_zh": ["西奥多·雅各布·弗雷林海森", "威廉·滕南特", "吉尔伯特·滕南特"], "what_en": "Pietism, a German movement from around 1700 stressing pious behavior and a mystical union with God through emotional worship, reached America with German migrants in the 1720s; Dutch minister Theodore Jacob Frelinghuysen preached it to German settlers, and William and Gilbert Tennent carried it to Scots-Irish Presbyterians.", "what_zh": "约1700年兴起于德意志、强调虔诚行为与通过情感崇拜与上帝神秘合一的虔敬主义，随德意志移民于1720年代抵达美洲；荷兰牧师弗雷林海森向德意志移民宣讲，威廉与吉尔伯特·滕南特父子把它带给苏格兰-爱尔兰长老会信徒。", "cause_en": "Many colonists found established churches cold and distant; Pietism appealed to hearts rather than minds, promising personal regeneration through divine grace.", "cause_zh": "许多殖民者觉得既定教会冷漠疏远；虔敬主义诉诸心灵而非头脑，应许借神恩获得个人重生。", "sig_en": "Pietist revivals were the seedbed of the Great Awakening: they created the itinerant, emotional preaching style and transatlantic networks that Whitefield would soon electrify.", "sig_zh": "虔敬主义复兴是大觉醒的苗圃：它创造了巡回情感布道的风格与跨大西洋网络，怀特菲尔德不久将使之沸腾。", "exp_en": "Pietism was the Enlightenment's mirror image: where reason promised progress, Pietism promised rebirth — and both traveled to America in the same ships of print and migration.", "exp_zh": "虔敬主义是启蒙运动的镜像：理性应许进步，虔敬主义应许重生——两者搭乘同样的印刷与移民之船抵达美洲。", "page": 129, "topic_es": "El pietismo en las colonias medias", "what_es": "El pietismo, un movimiento alemán de alrededor de 1700 que enfatizaba la conducta piadosa y una unión mística con Dios mediante el culto emocional, llegó a América con migrantes alemanes en la década de 1720; el ministro holandés Theodore Jacob Frelinghuysen lo predicó a colonos alemanes, y William y Gilbert Tennent lo llevaron a los presbiterianos escoceses-irlandeses.", "cause_es": "Muchos colonos encontraban las iglesias establecidas frías y distantes; el pietismo apelaba a los corazones más que a las mentes, prometiendo regeneración personal mediante la gracia divina.", "sig_es": "Los avivamientos pietistas fueron el semillero del Gran Despertar: crearon el estilo de predicación itinerante y emocional y las redes transatlánticas que Whitefield pronto electrificaría.", "exp_es": "El pietismo fue la imagen especular de la Ilustración: donde la razón prometía progreso, el pietismo prometía renacimiento — y ambos viajaron a América en los mismos barcos de imprenta y migración.", "who_es": ["Theodore Jacob Frelinghuysen", "William Tennent", "Gilbert Tennent"], "img": {"file": "img:f1_2279", "credit": "图源：Henretta《America's History》第8版 p.129"}}, {"id": "p2-033", "period": 2, "topic_en": "Great Awakening: Edwards and Whitefield (1739)", "topic_zh": "大觉醒：爱德华兹与怀特菲尔德（1739）", "year": 1739, "year_text": "1730s-1740s", "who": ["Jonathan Edwards", "George Whitefield", "John Wesley"], "who_zh": ["乔纳森·爱德华兹", "乔治·怀特菲尔德", "约翰·卫斯理"], "what_en": "Jonathan Edwards sparked revival in Northampton, Massachusetts in the 1730s, but English minister George Whitefield — a follower of John Wesley — transformed local revivals into a Great Awakening, carrying his dramatic, memorized sermons from Georgia to Massachusetts in 1739 and drawing huge crowds.", "what_zh": "乔纳森·爱德华兹1730年代在马萨诸塞北安普顿点燃复兴，但英国牧师乔治·怀特菲尔德——约翰·卫斯理的追随者——把地方复兴变成大觉醒，1739年带着戏剧性、脱稿的布道从佐治亚一路讲到马萨诸塞，吸引巨量听众。", "cause_en": "Pietist networks, the print revolution, and spiritual hunger in under-served congregations (half the pulpits in Pennsylvania's German churches stood empty) created an audience ready for 'heart religion.'", "cause_zh": "虔敬主义网络、印刷革命与人手不足的教会中的灵性饥渴（宾州德意志教会一半讲坛空置）造就了准备好接受“心灵宗教”的听众。", "sig_en": "The Awakening's converts — the 'New Lights' — challenged ministerial authority, undermined tax-supported churches, and learned to organize across colonies: a rehearsal for revolutionary mobilization.", "sig_zh": "觉醒的皈依者——“新光派”——挑战牧师权威，动摇税收供养的教会，并学会跨殖民地组织：这是革命动员的预演。", "src": {"text": "I was loaded with the guilt of Sin. . . . Hell fire was most always in my mind; and I have hundreds of times put my fingers into my pipe when I have been smoaking to feel how fire felt", "attr": "Nathan Cole, 'The Spiritual Travels of Nathan Cole, 1741'"}, "exp_en": "The Great Awakening democratized American religion: salvation by felt experience, not learned theology, made every believer a potential authority.", "exp_zh": "大觉醒使美国宗教民主化：靠感受经验而非学问神学得救，使每个信徒都成为潜在的权威。", "page": 129, "topic_es": "El Gran Despertar: Edwards y Whitefield (1739)", "what_es": "Jonathan Edwards desató el avivamiento en Northampton, Massachusetts, en la década de 1730, pero el ministro inglés George Whitefield — seguidor de John Wesley — transformó los avivamientos locales en un Gran Despertar, llevando sus sermones dramáticos y memorizados desde Georgia hasta Massachusetts en 1739 y atrayendo multitudes enormes.", "cause_es": "Las redes pietistas, la revolución de la imprenta y el hambre espiritual en congregaciones desatendidas (la mitad de los púlpitos de las iglesias alemanas de Pennsylvania estaban vacíos) crearon una audiencia lista para la 'religión del corazón'.", "sig_es": "Los conversos del Despertar — las 'Nuevas Luces' — desafiaron la autoridad ministerial, socavaron las iglesias sostenidas con impuestos y aprendieron a organizarse entre colonias: un ensayo de la movilización revolucionaria.", "exp_es": "El Gran Despertar democratizó la religión americana: la salvación por la experiencia sentida, no por la teología aprendida, hizo de cada creyente una autoridad potencial.", "who_es": ["Jonathan Edwards", "George Whitefield", "John Wesley"], "img": {"file": "img:f1_2279", "credit": "图源：Henretta《America's History》第8版 p.129"}}, {"id": "p2-034", "period": 2, "topic_en": "Old Lights vs. New Lights and new colleges", "topic_zh": "旧光派与新光派之争及新学院", "year": null, "year_text": "1740s-1760s", "who": ["Charles Chauncy", "Gilbert Tennent"], "who_zh": ["查尔斯·昌西", "吉尔伯特·滕南特"], "what_en": "Conservative 'Old Lights' like Boston's Charles Chauncy condemned revivalist 'cryings out, faintings and convulsions,' while 'New Lights' left the Congregational church to found 125 separatist churches; the competition also produced new colleges — Princeton (1746), King's College/Columbia (1754), Brown (1764), and Rutgers (1766).", "what_zh": "以波士顿查尔斯·昌西为代表的保守“旧光派”谴责复兴派的“哭喊、晕厥、抽搐”，“新光派”则脱离公理会建立125间分离教会；竞争还催生了新学院——普林斯顿（1746）、国王学院/哥伦比亚（1754）、布朗（1764）、罗格斯（1766）。", "cause_en": "Gilbert Tennent's pamphlet The Dangers of an Unconverted Ministry (1740) declared ministerial authority should come from conversion, not education — a direct assault on the learned clergy's status.", "cause_zh": "吉尔伯特·滕南特的小册子《未归正牧职的危险》（1740）宣称牧师权威应来自归正经历而非学问——直接冲击饱学牧师的地位。", "sig_en": "The split's main legacy was a new sense of authority among ordinary people — 'the poorest day-laborer holds it his right to advance his opinion' — and denominational colleges that would educate revolutionary leaders.", "sig_zh": "分裂的主要遗产是普通人新的权威感——“最穷的日工也认为有权发表宗教与政治见解”——以及培养革命领袖的各教派学院。", "why_term": "New Lights", "why_term_q": "大觉醒中支持复兴、强调归正经历的信徒被称为______。", "exp_en": "Old Lights vs. New Lights was America's first culture war: it asked who gets to speak for God — the educated or the converted — and the answer empowered the many.", "exp_zh": "旧光派与新光派之争是美国第一次文化战争：它追问谁有资格代上帝发言——有学问者还是归正者——答案赋权了大众。", "page": 132, "topic_es": "Viejas Luces contra Nuevas Luces y las nuevas universidades", "what_es": "Los conservadores 'Old Lights' como Charles Chauncy de Boston condenaban los 'gritos, desmayos y convulsiones' revivalistas, mientras las 'New Lights' abandonaban la iglesia congregacional para fundar 125 iglesias separatistas; la competencia también produjo nuevas universidades — Princeton (1746), King's College/Columbia (1754), Brown (1764) y Rutgers (1766).", "cause_es": "El panfleto de Gilbert Tennent The Dangers of an Unconverted Ministry (1740) declaró que la autoridad ministerial debía provenir de la conversión, no de la educación — un asalto directo al estatus del clero ilustrado.", "sig_es": "El principal legado de la división fue un nuevo sentido de autoridad entre la gente común — 'el jornalero más pobre considera su derecho expresar su opinión' — y universidades confesionales que educarían a líderes revolucionarios.", "exp_es": "'Viejas Luces' contra 'Nuevas Luces' fue la primera guerra cultural de América: preguntaba quién puede hablar por Dios — los educados o los convertidos — y la respuesta empoderó a los muchos.", "who_es": ["Charles Chauncy", "Gilbert Tennent"], "why_term_q_es": "Los creyentes que apoyaron el avivamiento durante el Gran Despertar y enfatizaron la experiencia de la conversión se denominan ______.", "img": {"file": "img:f1_2286", "credit": "图源：Henretta《America's History》第8版 p.132"}}, {"id": "p2-035", "period": 2, "topic_en": "Southern religious revivals: Presbyterians and Baptists", "topic_zh": "南方的宗教复兴：长老会与浸信会", "year": 1743, "year_text": "1743-1775", "who": ["Samuel Davies", "Samuel Morris"], "who_zh": ["塞缪尔·戴维斯", "塞缪尔·莫里斯"], "what_en": "In 1743 bricklayer Samuel Morris led Virginia Anglicans out of their church and invited New Light Presbyterian Samuel Davies, whose revivals threatened the gentry; then in the 1760s Baptist ministers with their adult-baptism, 'brother and sister' egalitarianism converted thousands — by 1775 about 15 percent of Virginia's whites and hundreds of enslaved blacks were Baptists.", "what_zh": "1743年泥瓦匠塞缪尔·莫里斯率弗吉尼亚圣公会信徒出走，邀来新光派长老会牧师塞缪尔·戴维斯，其复兴威胁乡绅权威；1760年代浸信会牧师以成人洗礼、“弟兄姊妹”平等主义使数千人归信——到1775年约15%的弗吉尼亚白人与数百黑奴加入浸信会。", "cause_en": "Anglican ministers ignored the spiritual needs of landless whites and African Americans, while the gentry used parish control to discipline clergy; dissenters offered emotional faith and social dignity.", "cause_zh": "圣公会牧师忽视无地白人与非裔的精神需求，乡绅则用堂区控制钳制牧师；异议派提供了情感信仰与社会尊严。", "sig_en": "The Baptist insurgency empowered poor tenants and yeomen, shrank the cultural gulf between blacks and whites as slaves converted, and undermined one justification for slavery — though it did not overturn gentry political control.", "sig_zh": "浸信会起义赋权贫穷佃农与自耕农，奴隶归信缩小了黑白文化鸿沟，动摇了奴隶制的一条辩护理由——虽未推翻乡绅的政治控制。", "exp_en": "In the South the Awakening became a social revolt: calling planters 'brother' was a theological act with revolutionary implications.", "exp_zh": "在南方，觉醒变成社会反抗：称种植园主为“弟兄”是具有革命含义的神学行为。", "page": 133, "topic_es": "Avivamientos religiosos sureños: presbiterianos y bautistas", "what_es": "En 1743 el albañil Samuel Morris sacó a los anglicanos de Virginia de su iglesia e invitó al presbiteriano Nueva Luz Samuel Davies, cuyos avivamientos amenazaron a la aristocracia; luego en la década de 1760 ministros bautistas con su bautismo de adultos y su igualitarismo de 'hermano y hermana' convirtieron a miles — hacia 1775 alrededor del 15 por ciento de los blancos de Virginia y cientos de negros esclavizados eran bautistas.", "cause_es": "Los ministros anglicanos ignoraban las necesidades espirituales de los blancos sin tierra y los afroamericanos, mientras la aristocracia usaba el control parroquial para disciplinar al clero; los disidentes ofrecían fe emocional y dignidad social.", "sig_es": "La insurgencia bautista empoderó a arrendatarios pobres y yeomen, redujo el abismo cultural entre negros y blancos a medida que los esclavos se convertían, y socavó una justificación de la esclavitud — aunque no derrocó el control político de la aristocracia.", "exp_es": "En el Sur el Despertar se volvió una revuelta social: llamar 'hermano' a los plantadores era un acto teológico con implicaciones revolucionarias.", "who_es": ["Samuel Davies", "Samuel Morris"]}, {"id": "p2-036", "period": 2, "topic_en": "Ohio Company grant (1748) and Washington's expedition (1754)", "topic_zh": "俄亥俄公司授地（1748）与华盛顿远征（1754）", "year": 1748, "year_text": "1748-1754", "who": ["George Washington", "Tanaghrisson"], "who_zh": ["乔治·华盛顿", "塔纳格里森"], "what_en": "In 1748 the Ohio Company of Virginia won a 200,000-acre crown grant on the upper Ohio, threatening French claims; in 1754 Governor Dinwiddie sent 22-year-old Colonel George Washington to reassert British claims, and after his party fired on a French detachment, the Iroquois half-king Tanaghrisson killed a French officer to ensure war — Washington was soon defeated.", "what_zh": "1748年弗吉尼亚俄亥俄公司获得王室在俄亥俄上游20万英亩授地，威胁法国主张；1754年丁威迪总督派22岁的乔治·华盛顿上校重申英国主张，其队伍向法军分遣队开火后，易洛魁“半王”塔纳格里森杀死一名法国军官以确保开战——华盛顿随即战败。", "cause_en": "British traders were drawing Ohio Indians away from French posts, and Virginia speculators wanted the valley; France answered by building a chain of forts ending in Fort Duquesne (Pittsburgh).", "cause_zh": "英国商人正把俄亥俄印第安人从法国据点拉走，弗吉尼亚投机者觊觎河谷；法国以修建一串堡垒回应，最终建成杜肯堡（匹兹堡）。", "sig_en": "The skirmish was the spark of the French and Indian War: an international incident that expansionists in Virginia and London used to demand a general war with France.", "sig_zh": "这次小冲突是法国印第安战争的火星：一起国际事件，被弗吉尼亚与伦敦的扩张主义者用来要求对法全面开战。", "exp_en": "The Ohio Valley shows how speculation started a world war: a land company's grant, a young colonel's blunder, and an Iroquois diplomat's calculation combined to ignite an empire-wide conflict.", "exp_zh": "俄亥俄河谷显示投机如何点燃世界大战：一家土地公司的授地、一位年轻上校的失误、一位易洛魁外交官的算计，共同点燃了帝国范围的冲突。", "page": 135, "topic_es": "La concesión de la Ohio Company (1748) y la expedición de Washington (1754)", "what_es": "En 1748 la Ohio Company de Virginia obtuvo una concesión real de 200.000 acres en el alto Ohio, amenazando las reclamaciones francesas; en 1754 el gobernador Dinwiddie envió al coronel George Washington, de 22 años, a reafirmar las reclamaciones británicas, y después de que su partida disparara contra un destacamento francés, el medio-rey iroqués Tanaghrisson mató a un oficial francés para asegurar la guerra — Washington pronto fue derrotado.", "cause_es": "Los comerciantes británicos estaban alejando a los indios de Ohio de los puestos franceses, y los especuladores de Virginia querían el valle; Francia respondió construyendo una cadena de fuertes que terminaba en Fort Duquesne (Pittsburgh).", "sig_es": "La escaramuza fue la chispa de la Guerra Franco-India: un incidente internacional que los expansionistas de Virginia y Londres usaron para exigir una guerra general con Francia.", "exp_es": "El valle de Ohio muestra cómo la especulación inició una guerra mundial: la concesión de una compañía de tierras, el error de un joven coronel y el cálculo de un diplomático iroqués se combinaron para encender un conflicto imperial.", "who_es": ["George Washington", "Tanaghrisson"]}, {"id": "p2-037", "period": 2, "topic_en": "Albany Congress and Franklin's Plan of Union (1754)", "topic_zh": "奥尔巴尼会议与富兰克林联合方案（1754）", "year": 1754, "year_text": "June 1754", "who": ["Benjamin Franklin", "Hendrick Peters Theyanoguin"], "who_zh": ["本杰明·富兰克林", "亨德里克·彼得斯·特亚诺金"], "what_en": "To repair the Covenant Chain, the Board of Trade called colonial delegates to Albany in June 1754, where Mohawk leader Hendrick Peters Theyanoguin challenged Britain to defend its interests and Benjamin Franklin proposed a Plan of Union: 'one general government' with a continental assembly managing trade, Indian policy, and defense.", "what_zh": "为修复契约链，贸易委员会1754年6月召集各殖民地代表到奥尔巴尼，莫霍克领袖亨德里克·彼得斯·特亚诺金敦促英国捍卫其利益，本杰明·富兰克林提出联合方案：建立“一个总政府”，设大陆议会管理贸易、印第安政策与防务。", "cause_en": "The Iroquois were unhappy that Britain neglected them while New York settlers pressed onto their lands, and the colonies were famously incapable of cooperating in their own defense.", "cause_zh": "易洛魁不满英国忽视他们而纽约移民蚕食其土地，各殖民地又出了名地无法在自卫上合作。", "sig_en": "The plan would have compromised both the assemblies' independence and Parliament's authority, so it 'never received serious consideration' — but it was the first concrete proposal for American intercolonial union.", "sig_zh": "方案会同时损害殖民地议会的独立与英国议会的权威，故“从未得到认真考虑”——但它是美洲殖民地间联合的第一个具体方案。", "exp_en": "Albany 1754 was a double failure that foreshadowed 1776: Indians told Britain its alliance was hollow, and Franklin showed colonists a union they were not yet ready to accept.", "exp_zh": "1754年奥尔巴尼是预示1776年的双重失败：印第安人告诉英国其盟约已空心化，富兰克林向殖民者展示了一个他们尚未准备好接受的联合。", "page": 137, "topic_es": "El Congreso de Albany y el Plan de Unión de Franklin (1754)", "what_es": "Para reparar la Covenant Chain, el Board of Trade convocó a delegados coloniales en Albany en junio de 1754, donde el líder mohawk Hendrick Peters Theyanoguin desafió a Gran Bretaña a defender sus intereses y Benjamin Franklin propuso un Plan de Unión: 'un gobierno general' con una asamblea continental que gestionara el comercio, la política india y la defensa.", "cause_es": "Los iroqueses estaban descontentos de que Gran Bretaña los descuidara mientras los colonos de New York presionaban sobre sus tierras, y las colonias eran famosamente incapaces de cooperar en su propia defensa.", "sig_es": "El plan habría comprometido tanto la independencia de las asambleas como la autoridad del Parlamento, así que 'nunca recibió seria consideración' — pero fue la primera propuesta concreta de unión intercolonial americana.", "exp_es": "Albany 1754 fue un doble fracaso que presagió 1776: los indios dijeron a Gran Bretaña que su alianza era hueca, y Franklin mostró a los colonos una unión que aún no estaban listos para aceptar.", "who_es": ["Benjamin Franklin", "Hendrick Peters Theyanoguin"], "img": {"file": "img:f1_2307", "credit": "图源：Henretta《America's History》第8版 p.137"}}, {"id": "p2-038", "period": 2, "topic_en": "Braddock's defeat and the Acadian deportation (1755)", "topic_zh": "布拉多克惨败与阿卡迪亚人大驱逐（1755）", "year": 1755, "year_text": "1755", "who": ["Edward Braddock", "George Washington"], "who_zh": ["爱德华·布拉多克", "乔治·华盛顿"], "what_en": "In July 1755 General Edward Braddock marched 1,500 British regulars and Virginia militiamen on Fort Duquesne but was routed by a French and Indian force — Braddock killed, over half his men killed or wounded; that same year New England troops deported nearly 10,000 French Acadians from Nova Scotia, scattering them to France, the West Indies, and Louisiana.", "what_zh": "1755年7月，爱德华·布拉多克将军率1500名英军正规军与弗吉尼亚民兵进攻杜肯堡，却被法印联军击溃——布拉多克阵亡，半数以上官兵死伤；同年新英格兰军队把近万名法裔阿卡迪亚人从新斯科舍驱逐，分散到法国、西印度群岛与路易斯安那。", "cause_en": "War hawks William Pitt and Lord Halifax had persuaded London to launch an American war; Braddock's contempt for Indian allies and colonial officers like Washington left him blind in the backcountry, while the Acadians were condemned as 'rebels' without property rights.", "cause_zh": "战争鹰派威廉·皮特与哈利法克斯勋爵说服伦敦发动美洲战争；布拉多克蔑视印第安盟友与华盛顿等殖民地军官，在边疆两眼一抹黑，阿卡迪亚人则被定为“叛逆者”、剥夺财产权。", "sig_en": "Braddock's defeat shattered faith in British military invincibility and taught Washington bitter lessons about European tactics in America; the Acadian deportation was ethnic cleansing that seeded the Cajun culture of Louisiana.", "sig_zh": "布拉多克惨败粉碎了对英军无敌的信念，也给华盛顿上了关于欧式战术在美洲水土不服的惨痛一课；驱逐阿卡迪亚人则是种族清洗，播下了路易斯安那卡津文化的种子。", "exp_en": "1755 was the year British arrogance met American reality: regulars died in formation in the woods while civilians were herded onto ships — the empire at its most brutal and most vulnerable.", "exp_zh": "1755年是英国傲慢撞上美洲现实的一年：正规军在林中列阵送死，平民被赶上船只——帝国最残酷也最脆弱的一面。", "page": 137, "topic_es": "La derrota de Braddock y la deportación de los acadianos (1755)", "what_es": "En julio de 1755 el general Edward Braddock marchó con 1.500 regulares británicos y milicianos de Virginia sobre Fort Duquesne, pero fue derrotado por una fuerza franco-india — Braddock muerto, más de la mitad de sus hombres muertos o heridos; ese mismo año tropas de New England deportaron a casi 10.000 acadianos franceses de Nova Scotia, dispersándolos a Francia, las Antillas y Louisiana.", "cause_es": "Los halcones de guerra William Pitt y Lord Halifax habían persuadido a Londres de lanzar una guerra americana; el desprecio de Braddock por los aliados indios y oficiales coloniales como Washington lo dejó ciego en la frontera, mientras los acadianos eran condenados como 'rebeldes' sin derechos de propiedad.", "sig_es": "La derrota de Braddock destrozó la fe en la invencibilidad militar británica y enseñó a Washington amargas lecciones sobre las tácticas europeas en América; la deportación acadiana fue una limpieza étnica que sembró la cultura cajún de Louisiana.", "exp_es": "1755 fue el año en que la arrogancia británica se topó con la realidad americana: los regulares morían en formación en los bosques mientras los civiles eran arreados a los barcos — el imperio en su forma más brutal y más vulnerable.", "who_es": ["Edward Braddock", "George Washington"], "img": {"file": "img:f1_2307", "credit": "图源：Henretta《America's History》第8版 p.137"}}, {"id": "p2-039", "period": 2, "topic_en": "Great War for Empire: Pitt and the conquest of Canada", "topic_zh": "帝国大战：皮特与征服加拿大", "year": 1756, "year_text": "1756-1763", "who": ["William Pitt", "James Wolfe"], "who_zh": ["老威廉·皮特", "詹姆斯·沃尔夫"], "what_en": "By 1756 the American war had become the global Seven Years' War — the Great War for Empire — and William Pitt, boasting 'I know that I can save this country,' committed 30,000 British soldiers and 1 million pounds a year to America; his forces took Quebec in 1759 under James Wolfe and completed the conquest of Canada with Montreal in 1760.", "what_zh": "到1756年美洲战争已演变为全球七年战争——帝国大战——威廉·皮特自夸“我知道我能拯救这个国家”，向美洲投入3万英军与每年100万英镑；其部队1759年在詹姆斯·沃尔夫率领下攻克魁北克，1760年攻占蒙特利尔完成对加拿大的征服。", "cause_en": "Pitt planned to cripple France by seizing its colonies, exploiting Britain's 14-to-1 demographic advantage in North America and paying half the cost of colonial troops to mobilize the colonists.", "cause_zh": "皮特计划以夺取殖民地拖垮法国，利用英国在北美14比1的人口优势，并承担殖民地军队一半费用以动员殖民者。", "sig_en": "Britain forged a nearly worldwide commercial and colonial empire — but the victory was bought with massive debt, and British officers' contempt for colonial soldiers ('the dirtiest, most contemptible, cowardly dogs') embittered the very allies London would soon tax.", "sig_zh": "英国锻造了近乎全球的商业殖民帝国——但胜利以巨额债务换来，英军军官对殖民地士兵的蔑视（“最肮脏、最可鄙、最懦弱的狗”）激怒了伦敦不久就要征税的盟友。", "exp_en": "Pitt won the empire and lost its loyalty: the Great War for Empire made Britain supreme and simultaneously manufactured the grievances — debt, arrogance, and a standing army — that would undo that supremacy.", "exp_zh": "皮特赢得了帝国却输掉了忠诚：帝国大战使英国登峰造极，也同时制造了将瓦解这一霸权的怨恨——债务、傲慢与常备军。", "page": 138, "topic_es": "La Gran Guerra por el Imperio: Pitt y la conquista de Canadá", "what_es": "Hacia 1756 la guerra americana se había vuelto la Guerra de los Siete Años global — la Gran Guerra por el Imperio — y William Pitt, jactándose de 'sé que puedo salvar este país', comprometió 30.000 soldados británicos y 1 millón de libras al año para América; sus fuerzas tomaron Quebec en 1759 bajo James Wolfe y completaron la conquista de Canadá con Montreal en 1760.", "cause_es": "Pitt planeaba paralizar a Francia apoderándose de sus colonias, explotando la ventaja demográfica británica de 14 a 1 en Norteamérica y pagando la mitad del costo de las tropas coloniales para movilizar a los colonos.", "sig_es": "Gran Bretaña forjó un imperio comercial y colonial casi mundial — pero la victoria se compró con una deuda masiva, y el desprecio de los oficiales británicos por los soldados coloniales ('los perros más sucios, despreciables y cobardes') amargó a los mismos aliados a quienes Londres pronto gravaría.", "exp_es": "Pitt ganó el imperio y perdió su lealtad: la Gran Guerra por el Imperio hizo suprema a Gran Bretaña y al mismo tiempo fabricó los agravios — deuda, arrogancia y un ejército permanente — que desharían esa supremacía.", "who_es": ["William Pitt", "James Wolfe"], "img": {"file": "img:f1_2310", "credit": "图源：Henretta《America's History》第8版 p.138"}}, {"id": "p2-040", "period": 2, "topic_en": "Treaty of Paris (1763)", "topic_zh": "《巴黎条约》（1763）", "year": 1763, "year_text": "1763", "who": [], "who_zh": [], "what_en": "The Treaty of Paris (1763) confirmed Britain's triumph: France ceded Canada and all its territory east of the Mississippi, and Spain ceded Florida, giving Britain sovereignty over half of North America — though at the West Indian sugar lobby's insistence, the rich islands of Martinique and Guadeloupe were returned to France.", "what_zh": "《巴黎条约》（1763）确认了英国的胜利：法国割让加拿大及密西西比河以东全部领土，西班牙割让佛罗里达，英国获得北美一半的主权——但在西印度糖业游说集团坚持下，富庶的马提尼克与瓜德罗普岛归还法国。", "cause_en": "Britain's global victories — Canada, Cuba, the Philippines, Senegal, and India — left France with no leverage, and London chose continental empire over Caribbean sugar islands to protect its planters' monopoly.", "cause_zh": "英国的全球胜利——加拿大、古巴、菲律宾、塞内加尔、印度——使法国毫无筹码，伦敦为保护本国种植园主垄断，选择了大陆帝国而非加勒比糖岛。", "sig_en": "Britain stood triumphant with a nearly worldwide empire, but removing France also removed the Native counterweight that had protected Indian peoples — and the French threat that had kept colonists dependent on Britain.", "sig_zh": "英国带着近乎全球的帝国凯旋，但法国的消失也消除了保护印第安人的制衡力量——以及曾使殖民者依赖英国的法国威胁。", "exp_en": "Paris 1763 was victory with a hidden price: the empire looked complete, but its two pillars — Indian diplomacy and colonial dependence — had just been knocked away.", "exp_zh": "1763年巴黎是代价隐形的胜利：帝国看似完整，但其两大支柱——印第安外交与殖民地依赖——已被抽走。", "page": 139, "topic_es": "Treaty of Paris (1763)", "what_es": "El Treaty of Paris (1763) confirmó el triunfo de Gran Bretaña: Francia cedió Canadá y todo su territorio al este del Mississippi, y España cedió Florida, dando a Gran Bretaña soberanía sobre la mitad de Norteamérica — aunque, ante la insistencia del lobby azucarero antillano, las ricas islas de Martinique y Guadeloupe fueron devueltas a Francia.", "cause_es": "Las victorias globales de Gran Bretaña — Canadá, Cuba, Filipinas, Senegal e India — dejaron a Francia sin influencia, y Londres eligió el imperio continental sobre las islas azucareras caribeñas para proteger el monopolio de sus plantadores.", "sig_es": "Gran Bretaña quedó triunfante con un imperio casi mundial, pero eliminar a Francia también eliminó el contrapeso nativo que había protegido a los pueblos indios — y la amenaza francesa que había mantenido a los colonos dependientes de Gran Bretaña.", "exp_es": "París 1763 fue una victoria con precio oculto: el imperio parecía completo, pero sus dos pilares — la diplomacia india y la dependencia colonial — acababan de ser derribados.", "who_es": [], "img": {"file": "img:f1_2312", "credit": "图源：Henretta《America's History》第8版 p.139"}}, {"id": "p2-041", "period": 2, "topic_en": "Pontiac's Rebellion and the Proclamation of 1763", "topic_zh": "庞蒂亚克起义与《1763年公告》", "year": 1763, "year_text": "1763", "who": ["Pontiac", "Neolin"], "who_zh": ["庞蒂亚克", "尼奥林"], "what_en": "Inspired by the Delaware prophet Neolin's call to expel all whites, Ottawa chief Pontiac led a 1763 uprising at Detroit; Indians across the Great Lakes and Ohio Valley seized nearly every British garrison west of Fort Niagara, besieged Fort Pitt, and killed or captured over 2,000 settlers — prompting the Royal Proclamation of 1763, which declared the trans-Appalachian west off-limits to colonial settlement.", "what_zh": "受特拉华先知尼奥林驱逐所有白人号召的鼓舞，渥太华首领庞蒂亚克1763年在底特律领导起义；大湖与俄亥俄河谷的印第安人攻占尼亚加拉堡以西几乎所有英军据点、围攻皮特堡，杀死或俘虏2000多名移民——促使英国发布《1763年公告》，宣布阿巴拉契亚以西禁止殖民者定居。", "cause_en": "Britain's conquest alarmed native peoples from New York to the Mississippi, who preferred a few French traders to thousands of Anglo-American settlers; Neolin preached that English 'sickness, smallpox, and their poison [rum] will destroy you entirely.'", "cause_zh": "英国的征服使从纽约到密西西比的原住民深感不安，他们宁要少数法国商人也不要数千英裔移民；尼奥林宣讲英国人的“疾病、天花和毒药（朗姆酒）将彻底毁灭你们”。", "sig_en": "It took Britain nearly two years to reclaim its posts, and the expensive lesson produced the Proclamation of 1763 — an edict confirming Indian control of the west that, the book notes, 'many colonists would ignore.'", "sig_zh": "英国花了近两年才收复据点，昂贵的教训催生了《1763年公告》——确认印第安人对西部控制的法令，但如书中所言“许多殖民者会无视它”。", "src": {"text": "If you suffer the English among you, you are dead men. Sickness, smallpox, and their poison [rum] will destroy you entirely.", "attr": "Neolin, Delaware prophet (1763)"}, "exp_en": "Pontiac's Rebellion proved that 1763 was not peace but a new war: Native peoples, not France, were now the obstacle to empire — and London's answer only angered the colonists it was meant to protect.", "exp_zh": "庞蒂亚克起义证明1763年不是和平而是新战争：挡住帝国的不是法国而是原住民——伦敦的回应只激怒了它本想保护的殖民者。", "page": 139, "topic_es": "La Rebelión de Pontiac y la Proclamación de 1763", "what_es": "Inspirado por el llamado del profeta delaware Neolin a expulsar a todos los blancos, el jefe ottawa Pontiac lideró un levantamiento en 1763 en Detroit; indios de los Grandes Lagos y el valle de Ohio tomaron casi todas las guarniciones británicas al oeste de Fort Niagara, sitiaron Fort Pitt y mataron o capturaron a más de 2.000 colonos — provocando la Proclamación Real de 1763, que declaró el oeste transapalachiano vedado al asentamiento colonial.", "cause_es": "La conquista británica alarmó a los pueblos nativos desde New York hasta el Mississippi, que preferían unos pocos comerciantes franceses a miles de colonos angloamericanos; Neolin predicaba que la 'enfermedad, la viruela y su veneno [el ron]' inglesa 'los destruiría por completo'.", "sig_es": "Gran Bretaña tardó casi dos años en recuperar sus puestos, y la costosa lección produjo la Proclamación de 1763 — un edicto que confirmaba el control indio del oeste y que, señala el libro, 'muchos colonos ignorarían'.", "exp_es": "La Rebelión de Pontiac probó que 1763 no era paz sino una nueva guerra: los pueblos nativos, no Francia, eran ahora el obstáculo para el imperio — y la respuesta de Londres solo enfureció a los colonos que pretendía proteger.", "who_es": ["Pontiac", "Neolin"], "img": {"file": "img:f1_2312", "credit": "图源：Henretta《America's History》第8版 p.139"}}, {"id": "p2-042", "period": 2, "topic_en": "Paxton Boys massacre (1763)", "topic_zh": "帕克斯顿男孩屠杀（1763）", "year": 1763, "year_text": "1763", "who": ["Benjamin Franklin"], "who_zh": ["本杰明·富兰克林"], "what_en": "In 1763 Scots-Irish frontiersmen called the Paxton Boys massacred twenty Conestoga Indians, a peaceful assimilated community; when Governor John Penn tried to prosecute them, 250 armed Scots-Irish marched on Philadelphia until Benjamin Franklin intercepted them at Lancaster and arranged a truce.", "what_zh": "1763年，被称为帕克斯顿男孩的苏格兰-爱尔兰边疆人屠杀了20名科内斯托加印第安人——一个和平同化的社群；当约翰·佩恩总督试图起诉凶手时，250名武装苏格兰-爱尔兰人进军费城，直到本杰明·富兰克林在兰卡斯特截住他们并达成停战。", "cause_en": "During the war Delaware and Shawnee warriors had destroyed Pennsylvania frontier farms in revenge for Thomas Penn's 1737 land swindle; Scots-Irish settlers demanded the expulsion of all Indians, but Quaker leaders refused.", "cause_zh": "战争期间特拉华与肖尼武士为报复托马斯·佩恩1737年的土地骗局摧毁了宾州边疆农场；苏格兰-爱尔兰移民要求驱逐所有印第安人，贵格会领袖拒绝。", "sig_en": "Prosecution failed for lack of witnesses, and the episode let the Paxton Boys' defenders denounce Pennsylvania's government for protecting Indians while neglecting backcountry colonists — a lasting east-west political wound.", "sig_zh": "因缺乏证人起诉失败，该事件让帕克斯顿男孩的辩护者得以谴责宾州政府保护印第安人却忽视边疆殖民者——留下持久的东西部政治裂痕。", "exp_en": "The Paxton Boys exposed the dark side of frontier democracy: popular violence claiming to speak for 'the people' against both Indians and an eastern government.", "exp_zh": "帕克斯顿男孩暴露了边疆民主的阴暗面：以“人民”名义针对印第安人与东部政府的民众暴力。", "page": 142, "topic_es": "La masacre de los Paxton Boys (1763)", "what_es": "En 1763 fronterizos escoceses-irlandeses llamados los Paxton Boys masacraron a veinte indios Conestoga, una comunidad pacífica asimilada; cuando el gobernador John Penn intentó procesarlos, 250 escoceses-irlandeses armados marcharon sobre Philadelphia hasta que Benjamin Franklin los interceptó en Lancaster y acordó una tregua.", "cause_es": "Durante la guerra, guerreros delaware y shawnee habían destruido granjas fronterizas de Pennsylvania en venganza por el fraude de tierras de Thomas Penn en 1737; los colonos escoceses-irlandeses exigían la expulsión de todos los indios, pero los líderes cuáqueros se negaban.", "sig_es": "El proceso fracasó por falta de testigos, y el episodio permitió a los defensores de los Paxton Boys denunciar al gobierno de Pennsylvania por proteger a los indios mientras descuidaba a los colonos de la frontera — una duradera herida política este-oeste.", "exp_es": "Los Paxton Boys expusieron el lado oscuro de la democracia fronteriza: violencia popular que pretendía hablar por 'el pueblo' contra los indios y contra un gobierno del este.", "who_es": ["Benjamin Franklin"], "img": {"file": "img:f1_2323", "credit": "图源：Henretta《America's History》第8版 p.142"}}, {"id": "p2-043", "period": 2, "topic_en": "Regulators of South and North Carolina", "topic_zh": "南北卡罗来纳的“调节者”运动", "year": 1771, "year_text": "1766-1771", "who": ["William Tryon"], "who_zh": ["威廉·特赖恩"], "what_en": "Backcountry Regulators demanded courts, fairer taxes, and representation from eastern-dominated governments: South Carolina's landowning vigilantes won western courts in 1767 but no reapportionment, while North Carolina's debtors closed courts and freed comrades from jail until Royal Governor William Tryon crushed them at Alamance in May 1771 — 30 dead, 7 leaders executed.", "what_zh": "边疆“调节者”要求东部主导的政府提供法院、公平税收与代表权：南卡拥有土地的义警在1767年赢得西部法院但未获重新分配议席，北卡负债农民则关闭法院、劫狱，直到王室总督威廉·特赖恩1771年5月在阿拉曼斯镇压他们——30人死亡、7名领袖被处决。", "cause_en": "The post-1763 recession collapsed tobacco prices, creditors seized debtors' property, and eastern assemblies taxed and judged the backcountry without representing it; the Regulators demanded tax payments in 'the produce of the country' and taxation 'in proportion to the profits arising from his estate.'", "cause_zh": "1763年后衰退使烟草价格崩盘，债权人没收负债农民财产，东部议会对边疆征税审判却不给代表权；调节者要求以“本地物产”纳税、按“地产收益比例”征税。", "sig_en": "The book ranks Alamance with Bacon's Rebellion (1675) and the 1688 uprisings as the great colonial political agitations — and notes that by the 1760s the mainland colonies had become complex societies 'with the potential to exist independently.'", "sig_zh": "该书把阿拉曼斯与培根起义（1675）、1688年起义并列为殖民地大政治骚动——并指出到1760年代本土殖民地已成为“有潜力独立存在”的复杂社会。", "exp_en": "The Regulators were the Revolution's backcountry rehearsal: farmers using disciplined mobs against courts and taxes, learning that eastern elites would answer petitions with troops.", "exp_zh": "调节者是革命的边疆预演：农民以有纪律的暴民对抗法院与税收，学到东部精英会用军队回应请愿。", "page": 142, "topic_es": "Los Reguladores de South y North Carolina", "what_es": "Los Reguladores de la frontera exigían tribunales, impuestos más justos y representación a gobiernos dominados por el este: los vigilantes terratenientes de South Carolina ganaron tribunales occidentales en 1767 pero sin redistribución, mientras los deudores de North Carolina cerraban tribunales y liberaban compañeros de la cárcel hasta que el gobernador real William Tryon los aplastó en Alamance en mayo de 1771 — 30 muertos, 7 líderes ejecutados.", "cause_es": "La recesión posterior a 1763 colapsó los precios del tabaco, los acreedores embargaban las propiedades de los deudores, y las asambleas del este gravaban y juzgaban a la frontera sin representarla; los Reguladores exigían pagar impuestos 'con los productos del país' y tributación 'en proporción a las ganancias de su hacienda'.", "sig_es": "El libro clasifica Alamance junto a la Rebelión de Bacon (1675) y los levantamientos de 1688 como las grandes agitaciones políticas coloniales — y señala que hacia la década de 1760 las colonias continentales se habían vuelto sociedades complejas 'con potencial para existir independientemente'.", "exp_es": "Los Reguladores fueron el ensayo de la Revolución en la frontera: agricultores usando turbas disciplinadas contra tribunales e impuestos, aprendiendo que las élites del este responderían a las peticiones con tropas.", "who_es": ["William Tryon"], "img": {"file": "img:f1_2323", "credit": "图源：Henretta《America's History》第8版 p.142"}}, {"id": "p2-044", "period": 2, "topic_en": "Land conflicts: Susquehanna Company and Hudson Valley tenant riots", "topic_zh": "土地冲突：萨斯奎汉纳公司与哈德逊河谷佃农骚乱", "year": 1749, "year_text": "1749-1760s", "who": ["Teedyuscung"], "who_zh": ["蒂迪乌斯康"], "what_en": "Land hunger ignited overlapping wars: Connecticut's Susquehanna Company (1749) claimed the Wyoming Valley against Pennsylvania's Penn proprietors — settlers burned rivals' barns, and Delaware headman Teedyuscung was burned to death in his cabin in April 1763 — while in the Hudson Valley, Dutch and English tenant farmers rioted to close courts enforcing the Van Rensselaers' and Livingstons' manorial claims.", "what_zh": "土地饥渴点燃重叠的战争：康涅狄格的萨斯奎汉纳公司（1749）依据“从海到海”特许状索要怀俄明谷，与宾州佩恩家族冲突——移民互烧谷仓，特拉华首领蒂迪乌斯康1763年4月在小屋中被烧死；哈德逊河谷的荷兰与英国佃农则骚乱关闭执行范伦塞勒与利文斯顿庄园主张的法院。", "cause_en": "Population growth made Atlantic coastal land ever more valuable, so landlords revived long-dormant seventeenth-century charters while migrants and speculators chased cheap land near the Appalachians.", "cause_zh": "人口增长使大西洋沿岸土地不断升值，地主复活长期休眠的17世纪特许状，移民与投机者则涌向阿巴拉契亚附近的廉价土地。", "sig_en": "The royal governor sent British troops to crush the tenant uprisings, showing that imperial power now served landlords against settlers — one more lesson in whose side the empire was on.", "sig_zh": "王室总督派英军镇压佃农起义，表明帝国权力如今为地主镇压移民服务——又一堂“帝国站在哪一边”的课。", "exp_en": "These land wars were class wars in colonial dress: ancient charters against living farmers, and the empire's bayonets backing the charters.", "exp_zh": "这些土地战争是穿着殖民外衣的阶级战争：古老特许状对活生生的农民，帝国的刺刀站在特许状一边。", "page": 141, "topic_es": "Conflictos de tierras: la Susquehanna Company y los disturbios de arrendatarios del valle del Hudson", "what_es": "El hambre de tierras encendió guerras superpuestas: la Susquehanna Company de Connecticut (1749) reclamó el valle de Wyoming contra los propietarios Penn de Pennsylvania — los colonos quemaban los graneros de sus rivales, y el líder delaware Teedyuscung murió quemado en su cabaña en abril de 1763 — mientras en el valle del Hudson, arrendatarios holandeses e ingleses se amotinaban para cerrar los tribunales que hacían cumplir las reclamaciones señoriales de los Van Rensselaer y los Livingston.", "cause_es": "El crecimiento demográfico hacía cada vez más valiosa la tierra costera atlántica, así que los terratenientes revivieron cartas del siglo XVII largamente dormidas mientras migrantes y especuladores perseguían tierra barata cerca de los Apalaches.", "sig_es": "El gobernador real envió tropas británicas a aplastar los levantamientos de arrendatarios, mostrando que el poder imperial ahora servía a los terratenientes contra los colonos — una lección más sobre de qué lado estaba el imperio.", "exp_es": "Estas guerras de tierras fueron guerras de clases con ropaje colonial: cartas antiguas contra agricultores vivos, y las bayonetas del imperio respaldando las cartas.", "who_es": ["Teedyuscung"], "img": {"file": "img:f1_2318", "credit": "图源：Henretta《America's History》第8版 p.141"}}, {"id": "p2-045", "period": 2, "topic_en": "Consumer revolution and colonial debt", "topic_zh": "消费革命与殖民地债务", "year": null, "year_text": "1750s-1770s", "who": [], "who_zh": [], "what_en": "Flooded with British manufactures on generous credit, colonists bought 30 percent of all British exports — but exports paid for only 80 percent of imports, and by 1772 the colonies had run up a cumulative debt of 2 million pounds; when Pitt's military subsidies ended in 1763, the colonies fell into recession.", "what_zh": "在慷慨赊销下涌入的英国制成品使殖民者买下英国出口的30%——但出口只够支付进口的80%，到1772年殖民地累积债务达200万英镑；1763年皮特的军事补贴一停，殖民地陷入衰退。", "cause_en": "English and Scottish merchants extended a full year of credit instead of six months to market factory goods, and wartime prosperity masked a structural trade deficit financed by British credit.", "cause_zh": "英苏商人把赊账期从半年延到一年以推销工厂货，战时繁荣掩盖了靠英国信贷支撑的结构性贸易逆差。", "sig_en": "The debt crisis made Americans more dependent on overseas credit and markets — and when London later tried to make them pay imperial costs through taxes, indebted colonists felt the squeeze twice over.", "sig_zh": "债务危机使美国人更依赖海外信贷与市场——当伦敦日后试图通过征税让他们分担帝国开支时，负债的殖民者感到双重挤压。", "exp_en": "The consumer revolution was prosperity on credit: it raised living standards and mortgaged the colonial future — the material backdrop of the coming imperial crisis.", "exp_zh": "消费革命是赊账的繁荣：它提高了生活水平，也抵押了殖民地的未来——是即将到来的帝国危机的物质背景。", "page": 141, "topic_es": "La revolución del consumo y la deuda colonial", "what_es": "Inundados de manufacturas británicas a crédito generoso, los colonos compraban el 30 por ciento de todas las exportaciones británicas — pero las exportaciones pagaban solo el 80 por ciento de las importaciones, y hacia 1772 las colonias habían acumulado una deuda de 2 millones de libras; cuando los subsidios militares de Pitt terminaron en 1763, las colonias cayeron en recesión.", "cause_es": "Los comerciantes ingleses y escoceses extendían un año completo de crédito en lugar de seis meses para colocar productos fabriles, y la prosperidad bélica enmascaraba un déficit comercial estructural financiado con crédito británico.", "sig_es": "La crisis de deuda hizo a los americanos más dependientes del crédito y los mercados ultramarinos — y cuando Londres más tarde intentó hacerles pagar los costos imperiales mediante impuestos, los colonos endeudados sintieron el apretón por partida doble.", "exp_es": "La revolución del consumo fue prosperidad a crédito: elevó el nivel de vida e hipotecó el futuro colonial — el telón de fondo material de la crisis imperial venidera.", "who_es": [], "img": {"file": "img:f1_2318", "credit": "图源：Henretta《America's History》第8版 p.141"}}];